pub(crate) fn real_sha512(data: &[u8]) -> Vec<u8> {
    let mut h: [u64; 8] = [
        0x6a09e667f3bcc908,
        0xbb67ae8584caa73b,
        0x3c6ef372fe94f82b,
        0xa54ff53a5f1d36f1,
        0x510e527fade682d1,
        0x9b05688c2b3e6c1f,
        0x1f83d9abfb41bd6b,
        0x5be0cd19137e2179,
    ];

    // Pre-processing: pad message to 1024-bit blocks
    let bit_len = (data.len() as u128).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 128 != 112 {
        msg.push(0x00);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());

    // Process each 1024-bit (128-byte) block
    for chunk in msg.chunks_exact(128) {
        let mut w = [0u64; 80];
        for i in 0..16 {
            w[i] = u64::from_be_bytes([
                chunk[8 * i],
                chunk[8 * i + 1],
                chunk[8 * i + 2],
                chunk[8 * i + 3],
                chunk[8 * i + 4],
                chunk[8 * i + 5],
                chunk[8 * i + 6],
                chunk[8 * i + 7],
            ]);
        }
        for i in 16..80 {
            let s0 = w[i - 15].rotate_right(1) ^ w[i - 15].rotate_right(8) ^ (w[i - 15] >> 7);
            let s1 = w[i - 2].rotate_right(19) ^ w[i - 2].rotate_right(61) ^ (w[i - 2] >> 6);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..80 {
            let s1 = e.rotate_right(14) ^ e.rotate_right(18) ^ e.rotate_right(41);
            let ch = (e & f) ^ ((!e) & g);
            let temp1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(SHA512_K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(28) ^ a.rotate_right(34) ^ a.rotate_right(39);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);

            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(temp1);
            d = c;
            c = b;
            b = a;
            a = temp1.wrapping_add(temp2);
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }

    let mut result = Vec::with_capacity(64);
    for word in &h {
        result.extend_from_slice(&word.to_be_bytes());
    }
    result
}

/// SHA-384 is SHA-512 with different initial values, truncated to 384 bits (48 bytes).
pub(crate) fn real_sha384(data: &[u8]) -> Vec<u8> {
    let mut h: [u64; 8] = [
        0xcbbb9d5dc1059ed8,
        0x629a292a367cd507,
        0x9159015a3070dd17,
        0x152fecd8f70e5939,
        0x67332667ffc00b31,
        0x8eb44a8768581511,
        0xdb0c2e0d64f98fa7,
        0x47b5481dbefa4fa4,
    ];

    // Same padding as SHA-512: 1024-bit blocks
    let bit_len = (data.len() as u128).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 128 != 112 {
        msg.push(0x00);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());

    for chunk in msg.chunks_exact(128) {
        let mut w = [0u64; 80];
        for i in 0..16 {
            w[i] = u64::from_be_bytes([
                chunk[8 * i],
                chunk[8 * i + 1],
                chunk[8 * i + 2],
                chunk[8 * i + 3],
                chunk[8 * i + 4],
                chunk[8 * i + 5],
                chunk[8 * i + 6],
                chunk[8 * i + 7],
            ]);
        }
        for i in 16..80 {
            let s0 = w[i - 15].rotate_right(1) ^ w[i - 15].rotate_right(8) ^ (w[i - 15] >> 7);
            let s1 = w[i - 2].rotate_right(19) ^ w[i - 2].rotate_right(61) ^ (w[i - 2] >> 6);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..80 {
            let s1 = e.rotate_right(14) ^ e.rotate_right(18) ^ e.rotate_right(41);
            let ch = (e & f) ^ ((!e) & g);
            let temp1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(SHA512_K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(28) ^ a.rotate_right(34) ^ a.rotate_right(39);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);

            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(temp1);
            d = c;
            c = b;
            b = a;
            a = temp1.wrapping_add(temp2);
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }

    // Truncate to 384 bits (6 words = 48 bytes)
    let mut result = Vec::with_capacity(48);
    for word in &h[..6] {
        result.extend_from_slice(&word.to_be_bytes());
    }
    result
}

// ===========================================================================
// Generic HMAC construction (RFC 2104)
// ===========================================================================

/// Generic HMAC: HMAC(K, data) = H((K' ⊕ opad) || H((K' ⊕ ipad) || data))
/// `hash_fn` is the underlying hash, `block_size` is the hash's internal block size.
fn hmac_generic(
    key: &[u8],
    data: &[u8],
    hash_fn: fn(&[u8]) -> Vec<u8>,
    block_size: usize,
) -> Vec<u8> {
    // Step 1: If key > block size, hash it; if shorter, pad with zeros
    let mut key_block = vec![0u8; block_size];
    if key.len() > block_size {
        let hashed = hash_fn(key);
        key_block[..hashed.len()].copy_from_slice(&hashed);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }

    // Step 2: Create inner and outer padded keys
    let mut i_key_pad = vec![0u8; block_size];
    let mut o_key_pad = vec![0u8; block_size];
    for i in 0..block_size {
        i_key_pad[i] = key_block[i] ^ 0x36;
        o_key_pad[i] = key_block[i] ^ 0x5c;
    }

    // Step 3: inner hash = H(i_key_pad || data)
    let mut inner_msg = Vec::with_capacity(block_size + data.len());
    inner_msg.extend_from_slice(&i_key_pad);
    inner_msg.extend_from_slice(data);
    let inner_hash = hash_fn(&inner_msg);

    // Step 4: outer hash = H(o_key_pad || inner_hash)
    let mut outer_msg = Vec::with_capacity(block_size + inner_hash.len());
    outer_msg.extend_from_slice(&o_key_pad);
    outer_msg.extend_from_slice(&inner_hash);
    hash_fn(&outer_msg)
}

/// HMAC-SHA-384 (128-byte block size, same as SHA-512)
pub(crate) fn hmac_sha384(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_sha384, 128)
}

/// HMAC-SHA-512 (128-byte block size)
pub(crate) fn hmac_sha512(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_sha512, 128)
}

/// HMAC-SHA-1 (64-byte block size)
pub(crate) fn hmac_sha1(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_sha1, 64)
}

/// HMAC-MD5 (64-byte block size)
pub(crate) fn hmac_md5(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_md5, 64)
}

fn native_md_digest(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let algo = match ctx.get_field(this, MD_FIELD_ALGO) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let data_arr = match ctx.get_field(this, MD_FIELD_DATA) {
        Value::Object(Some(o)) => o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let len = ctx.array_length(data_arr);
    let mut data = Vec::with_capacity(len);
    for i in 0..len {
        if let Value::Int(b) = ctx.get_array_element(data_arr, i) {
            data.push(b as u8);
        }
    }
    let digest = compute_digest(&algo, &data)?;
    // GC-safety: `this` is a bare Rust local (from `args.first()`) held
    // across two further allocating calls below (`new_array` x2). Either
    // can trigger a moving GC that relocates `this`; the final "reset"
    // `set_field` must re-read through a pin or it silently lands on an
    // abandoned from-space copy, leaving the live instance's accumulator
    // un-reset -- same unread-pin anti-pattern fixed in
    // `populate_real_thread_holder` (GCBARRIER-CDLWAIT-FIX, 2026-07-17).
    let this_handle = ctx.pin_native_root(this);
    let result = ctx.new_array(cratonvm_types::ArrayElementType::Byte, digest.len());
    let result_handle = ctx.pin_native_root(result);
    for (i, &b) in digest.iter().enumerate() {
        ctx.set_array_element(result, i, Value::Int(b as i8 as i32));
    }
    // Reset
    let empty = ctx.new_array(cratonvm_types::ArrayElementType::Byte, 0);
    let this = ctx.read_native_pin(this_handle, this);
    let result = ctx.read_native_pin(result_handle, result);
    ctx.set_field(this, MD_FIELD_DATA, Value::Object(Some(empty)));
    ctx.unpin_native_roots(this_handle);
    Ok(Some(Value::Object(Some(result))))
}

fn native_md_digest_input(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    // update with input first
    if let Some(Value::Object(Some(arr))) = args.get(1) {
        let len = ctx.array_length(*arr);
        let mut bytes = Vec::with_capacity(len);
        for i in 0..len {
            if let Value::Int(b) = ctx.get_array_element(*arr, i) {
                bytes.push(b as u8);
            }
        }
        md_append_bytes(ctx, this, &bytes);
    }
    native_md_digest(ctx, args)
}

/// `int MessageDigest.digest(byte[] buf, int offset, int len)` — completes the
/// digest into the caller's buffer and returns the number of bytes written.
/// Without this native the call ran the real JDK bytecode, which dispatches to
/// the abstract `MessageDigestSpi.engineDigest()` (no Code attribute) and threw
/// `AbstractMethodError` — e.g. Kafka's `SkimpyOffsetMap.hashInto` uses this
/// overload (OffsetMapTest), not the `digest()[B` form the other natives cover.
fn native_md_digest_buf(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let buf = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let offset = match args.get(2) {
        Some(Value::Int(v)) => (*v).max(0) as usize,
        _ => 0,
    };
    let len = match args.get(3) {
        Some(Value::Int(v)) => (*v).max(0) as usize,
        _ => 0,
    };
    let algo = match ctx.get_field(this, MD_FIELD_ALGO) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let data = match ctx.get_field(this, MD_FIELD_DATA) {
        Value::Object(Some(arr)) => {
            let n = ctx.array_length(arr);
            let mut v = Vec::with_capacity(n);
            for i in 0..n {
                if let Value::Int(b) = ctx.get_array_element(arr, i) {
                    v.push(b as u8);
                }
            }
            v
        }
        _ => Vec::new(),
    };
    let digest = compute_digest(&algo, &data)?;
    // JDK writes the full digest (callers size `len` to the digest length); we
    // additionally clamp to both `len` and the array bounds to fail safe.
    let cap = ctx.array_length(buf);
    let n = digest.len().min(len).min(cap.saturating_sub(offset));
    for i in 0..n {
        ctx.set_array_element(buf, offset + i, Value::Int(digest[i] as i8 as i32));
    }
    // Reset the running state, matching `digest()`'s post-finalization reset.
    let empty = ctx.new_array(cratonvm_types::ArrayElementType::Byte, 0);
    ctx.set_field(this, MD_FIELD_DATA, Value::Object(Some(empty)));
    Ok(Some(Value::Int(digest.len() as i32)))
}

fn native_md_reset(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let empty = ctx.new_array(cratonvm_types::ArrayElementType::Byte, 0);
    ctx.set_field(this, MD_FIELD_DATA, Value::Object(Some(empty)));
    Ok(None)
}

fn native_md_get_algorithm(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    Ok(Some(ctx.get_field(this, MD_FIELD_ALGO)))
}

fn native_md_get_digest_length(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let algo = match ctx.get_field(this, MD_FIELD_ALGO) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    // A THIRD hand-maintained digest-length table stood here, and it had
    // drifted furthest of the three: no MD2, no SHA-224, no SHA-512/224, no
    // SHA-512/256, no SHA3-224, and — because it only stripped `-` and not `/`
    // — `SHA-512/256` fell through the `_ => 32` default and reported 32 by
    // accident rather than by arm. Every one of those `compute_digest`
    // implements, so `getDigestLength()` was contradicting `digest()` on five
    // algorithms in synthetic mode.
    //
    // Adding MD2 and the SHAKE digests would have made that worse rather than
    // better: `getInstance` now admits them, so MD2 would have reported 32
    // where the digest is 16 and SHAKE256-512 would have reported 32 where the
    // digest is 64. One predicate, one length table, every door —
    // W7-63-jca-advertise-vs-serve.md.
    //
    // `None` is unreachable through either `getInstance` (both gate on
    // `algorithm_supported` first) and reports 0 rather than a plausible 32,
    // because a corroborating-but-wrong length is what made the SHA-256
    // fallback invisible in the first place.
    let len = crate::jca::message_digest::digest_length_bytes_public(&algo).unwrap_or(0);
    Ok(Some(Value::Int(len as i32)))
}

// SecureRandom — uses OS cryptographic entropy (BCryptGenRandom / /dev/urandom)
// for all random generation. The previous splitmix64 PRNG has been removed from
// all SecureRandom paths to prevent predictable output.

/// Fill a buffer with OS cryptographic entropy.
/// Mirrors crypto_impl::os_random_bytes but inlined here to avoid
/// feature-gate dependency on legacy-synthetic-crypto.
fn sr_os_random_bytes(buf: &mut [u8]) -> bool {
    #[cfg(target_os = "windows")]
    {
        #[link(name = "advapi32")]
        extern "system" {
            #[link_name = "SystemFunction036"]
            fn RtlGenRandom(buf: *mut u8, len: u32) -> u8;
        }
        for chunk in buf.chunks_mut(u32::MAX as usize) {
            let ok = unsafe { RtlGenRandom(chunk.as_mut_ptr(), chunk.len() as u32) };
            if ok == 0 {
                return false;
            }
        }
        true
    }
    #[cfg(not(target_os = "windows"))]
    {
        use std::io::Read;
        if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
            return f.read_exact(buf).is_ok();
        }
        false
    }
}

/// Get a cryptographically random u64 from OS entropy.
fn sr_os_random_u64() -> u64 {
    let mut buf = [0u8; 8];
    if !sr_os_random_bytes(&mut buf) {
        // Fallback: system_entropy_seed uses RandomState which itself uses OS entropy
        return system_entropy_seed();
    }
    u64::from_le_bytes(buf)
}

/// Gather entropy from multiple system sources and mix them into a seed.
/// Used only as a last-resort fallback when direct OS entropy fails.
fn system_entropy_seed() -> u64 {
    use std::collections::hash_map::RandomState;
    use std::hash::{BuildHasher, Hasher};
    let s = RandomState::new();
    let mut h = s.build_hasher();
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64;
    h.write_u64(nanos);
    let tid = format!("{:?}", std::thread::current().id());
    h.write(tid.as_bytes());
    let s2 = RandomState::new();
    let h2 = s2.build_hasher();
    h.write_u64(h2.finish());
    h.finish()
}

fn native_secure_random_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let seed = sr_os_random_u64() as i64;
    ctx.set_field(this, 0, Value::Long(seed));
    ctx.set_field(this, 1, Value::Int(0));
    Ok(None)
}

fn sr_next_seed(ctx: &mut dyn NativeContext, this: ObjectRef) -> i64 {
    // Use OS entropy directly for each call (CSPRNG).
    // The object's seed field is updated for compatibility but the output
    // comes from the OS, not from a deterministic PRNG.
    let val = sr_os_random_u64();
    ctx.set_field(this, 0, Value::Long(val as i64));
    val as i64
}

// ---------------------------------------------------------------------------
// StampedLock — real implementation backed by `stamped_lock` module.
// ---------------------------------------------------------------------------
//
// WP4.7: The earlier version of this code did `monitor_enter; monitor_wait(5);
// monitor_exit` between observing the state and parking, so a notification
// arriving in that gap was lost — writers blocked for the full 5 ms even
// when contention had already cleared. The fix is to hold a real
// `parking_lot::Mutex` across the check-and-park so `Condvar::wait`
// releases it atomically. All of that lives in `crate::stamped_lock` so
// it can be unit-tested independently of the NativeContext plumbing.
//
// State encoding (see `stamped_lock` module for the full rationale):
//   stamp: i64   — even = no writer, odd = writer active. Starts at 256.
//   readers: i32 — number of active read locks.

const STAMPED_ORIGIN: i64 = crate::stamped_lock::STAMPED_ORIGIN;

// ---------------------------------------------------------------------------
// GC-stable lock-identity key (Pattern-A fix, bug nb-lib-gckeys §1)
//
// The StampedLock / ReentrantReadWriteLock state tables in `stamped_lock`
// are keyed by a `usize` derived from the Java lock object. The previous
// derivation — `o.as_ptr() as usize` — is NOT stable under a moving GC:
// a thread that locks before a young-gen collection computes one key, the
// object is relocated, and the matching `unlock` (after the GC) recomputes
// a DIFFERENT key from the new address → it misses the slot it locked,
// leaving the original slot permanently write-/read-held (deadlock) or
// corrupting an unrelated slot that happens to land at the freed address.
//
// Fix: derive the key from a GC-stable identity. `ctx.identity_hash_code`
// survives relocation (the header hash is preserved/remapped by the
// collector), and a small per-hash generation registry disambiguates the
// rare genuine 32-bit identity-hash collision among live lock objects —
// exactly the scheme `properties_sidetable::key_for` and
// `native-collections`' `widened_obj_key` use. Routing both `stamped_addr`
// and `rwl_parent_addr` through this single helper keeps the lock and
// unlock paths agreeing on a key that no GC can shift.
struct LockKeyEntry {
    last_ptr: usize,
    generation: u32,
}

fn lock_key_registry() -> &'static parking_lot::Mutex<rustc_hash::FxHashMap<u32, Vec<LockKeyEntry>>>
{
    static R: std::sync::OnceLock<
        parking_lot::Mutex<rustc_hash::FxHashMap<u32, Vec<LockKeyEntry>>>,
    > = std::sync::OnceLock::new();
    R.get_or_init(|| parking_lot::Mutex::new(rustc_hash::FxHashMap::default()))
}

#[inline]
fn pack_lock_key(hash: u32, generation: u32) -> usize {
    ((hash as usize) << 32) | (generation as usize)
}

/// Map a Java lock object (or the parent RWL of a read/write view) to a
/// GC-stable `usize` key for the `stamped_lock` state tables. See the
/// module-level note above for the moving-GC deadlock this prevents. The
/// algorithm mirrors `properties_sidetable::key_for`:
///   1. same object seen again at the same address → reuse its generation;
///   2. lone occupant of this hash whose address moved (GC relocation) →
///      rebind to the new address (only when `hash != 0`, i.e. a real
///      assigned identity — hash 0 means "identity not yet assigned" and
///      DISTINCT objects all bucket there, so we must NOT merge them);
///   3. otherwise a new object / genuine collision → fresh generation.
fn gc_stable_lock_key(
    ctx: &mut dyn NativeContext,
    obj: ObjectRef,
) -> Result<usize, MethodCallFailed> {
    let hash = ctx.identity_hash_code(obj) as u32;
    let ptr = obj.as_ptr() as usize;
    let mut reg = lock_key_registry().lock();
    let slots = reg.entry(hash).or_default();
    if let Some(slot) = slots.iter().find(|s| s.last_ptr == ptr) {
        return Ok(pack_lock_key(hash, slot.generation));
    }
    if hash != 0 && slots.len() == 1 {
        slots[0].last_ptr = ptr;
        return Ok(pack_lock_key(hash, slots[0].generation));
    }
    let generation = slots.len() as u32;
    slots.push(LockKeyEntry {
        last_ptr: ptr,
        generation,
    });
    Ok(pack_lock_key(hash, generation))
}

fn mirror_stamped_state(ctx: &mut dyn NativeContext, obj: ObjectRef, addr: usize) {
    ctx.set_field_by_name(
        obj,
        "state",
        Value::Long(crate::stamped_lock::stamped_visible_state(addr)),
    );
}

// --- LongAdder ---
//
// Round-7 HIGH native-builtins #16 fix: stripe the LongAdder across a fixed
// pool of cells (real Striped64 grows up to NCPU; we use a constant 8-wide
// table for simplicity and call it good enough). Single-cell adders
// collapse to AtomicLong under contention, defeating LongAdder's entire
// purpose. With striping, contending threads hash to different cells and
// only conflict pairwise on hash collision.
//
// Cell storage lives in a process-wide side table keyed by the LongAdder
// `ObjectRef`'s raw pointer. We cannot reshape the JDK's LongAdder synthetic
// layout (other natives + reflection read field 0 as the `base` long), so
// the cells are stored out-of-band. `base` (field 0) is the uncontended
// path; the cells absorb contention.
//
// `sum()` returns `base + cells.iter().sum()`. `reset()` zeroes both. The
// per-cell atomicity guarantee from the previous CAS-loop is preserved.

/// Number of striped cells per LongAdder. The real JDK grows up to NCPU
/// rounded to a power of two. 8 is a fixed compromise: enough to give
/// 8-way concurrent throughput without per-process state growth.
const LA_CELL_COUNT: usize = 8;

struct LongAdderCells {
    /// One i64 per stripe. We use `std::sync::atomic::AtomicI64` so the
    /// per-cell CAS is a plain hardware atomic — no lock + no map lookup
    /// per add.
    cells: [std::sync::atomic::AtomicI64; LA_CELL_COUNT],
}

impl Default for LongAdderCells {
    fn default() -> Self {
        // `AtomicI64` is not `Copy`, so we cannot use `[expr; N]` syntax —
        // build the array explicitly. The constant must match
        // `LA_CELL_COUNT`; bump both if the stripe width changes.
        Self {
            cells: [
                std::sync::atomic::AtomicI64::new(0),
                std::sync::atomic::AtomicI64::new(0),
                std::sync::atomic::AtomicI64::new(0),
                std::sync::atomic::AtomicI64::new(0),
                std::sync::atomic::AtomicI64::new(0),
                std::sync::atomic::AtomicI64::new(0),
                std::sync::atomic::AtomicI64::new(0),
                std::sync::atomic::AtomicI64::new(0),
            ],
        }
    }
}

// Round-9 CRIT GC-correctness fix: key by `identity_hash_code(this)` not
// by raw `this.as_ptr() as usize`. Under a moving collector the
// LongAdder is invisibly relocated and the table loses its cell strip,
// silently dropping every striped add (LongAdder.sum() then under-reports
// by the lost cells). `identity_hash_code` is GC-stable — see
// `gc/src/compact_header.rs` HashCodeTable::update_after_gc.
fn long_adder_cells_table(
) -> &'static parking_lot::Mutex<rustc_hash::FxHashMap<i32, std::sync::Arc<LongAdderCells>>> {
    static TABLE: std::sync::OnceLock<
        parking_lot::Mutex<rustc_hash::FxHashMap<i32, std::sync::Arc<LongAdderCells>>>,
    > = std::sync::OnceLock::new();
    TABLE.get_or_init(|| parking_lot::Mutex::new(rustc_hash::FxHashMap::default()))
}

/// Fetch (or lazily create) the cell strip for a LongAdder instance. The
/// returned `Arc` lives for the lifetime of the table (we never evict —
/// the cells follow the LongAdder's heap lifetime, and our process-lifetime
/// heap means there is no use-after-free risk for the contained
/// `AtomicI64`s). Keyed by GC-stable `identity_hash_code`.
fn long_adder_cells(
    ctx: &mut dyn NativeContext,
    this: ObjectRef,
) -> std::sync::Arc<LongAdderCells> {
    let key = ctx.identity_hash_code(this);
    let mut t = long_adder_cells_table().lock();
    t.entry(key)
        .or_insert_with(|| std::sync::Arc::new(LongAdderCells::default()))
        .clone()
}

/// Pick a stripe index for the current thread. Round-9 CRIT-5 fix:
/// `std::thread::ThreadId` is allocated as a dense sequential counter
/// (1, 2, 3, ...), and the low bits of `FxHash(small dense integers)` are
/// highly correlated — eight threads mapping to indices via
/// `FxHash(tid) & 7` would frequently collide on the same cell, defeating
/// the stripe's purpose. Mix with the Fibonacci constant
/// `0x9E37_79B9_7F4A_7C15` (golden-ratio multiplier; same constant used
/// by `gc::collector::volatile_stripe_lock`) and take the high bits.
fn long_adder_stripe() -> usize {
    use std::hash::{Hash, Hasher};
    // std::thread::ThreadId has no public `as_u64`; pipe it through a tiny
    // FxHasher to extract a stable 64-bit value, then apply the Fibonacci
    // spread and take the high bits as the 8-cell index.
    let mut h = rustc_hash::FxHasher::default();
    std::thread::current().id().hash(&mut h);
    let tid_u64 = h.finish();
    ((tid_u64.wrapping_mul(0x9E37_79B9_7F4A_7C15)) >> 56) as usize & (LA_CELL_COUNT - 1)
}

/// Resolve `Striped64.base` to its absolute inherited-field slot.
///
/// Real JDK 25 lays out `Striped64` as `cells`, `base`, `cellsBusy`, so the
/// historical slot-0 assumption targets the reference-valued `cells` field.
/// Keep slot 0 only as a fallback for synthetic one-field objects used by the
/// native unit tests and stub-JDK mode.
fn striped64_base_slot_from_layout(
    resolved_base: Option<usize>,
    object_num_fields: usize,
) -> Option<usize> {
    resolved_base.or_else(|| (object_num_fields > 0).then_some(0))
}

fn striped64_base_slot(ctx: &dyn NativeContext, this: ObjectRef) -> Option<usize> {
    striped64_base_slot_from_layout(
        ctx.resolve_field_index("java/util/concurrent/atomic/Striped64", "base"),
        ctx.object_num_fields(this),
    )
}

#[cfg(test)]
mod striped64_base_slot_tests {
    use super::striped64_base_slot_from_layout;
    #[allow(unused_imports)]
    use cratonvm_native_api::{
        NativeClassAccess, NativeExceptionAccess, NativeGpuAccess, NativeHeapAccess,
        NativeInvokeAccess, NativeSystemAccess, NativeThreadAccess,
    };

    #[test]
    fn real_jdk_inherited_base_slot_wins_over_synthetic_fallback() {
        assert_eq!(striped64_base_slot_from_layout(Some(1), 3), Some(1));
    }

    #[test]
    fn one_field_synthetic_adder_keeps_slot_zero_fallback() {
        assert_eq!(striped64_base_slot_from_layout(None, 1), Some(0));
        assert_eq!(striped64_base_slot_from_layout(None, 0), None);
    }
}

fn native_long_adder_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    if let Some(base_slot) = striped64_base_slot(ctx, this) {
        ctx.set_field(this, base_slot, Value::Long(0));
    }
    // Pre-allocate the cell strip so the first `add` does not race the
    // map insert under the side-table mutex.
    let _ = long_adder_cells(ctx, this);
    Ok(None)
}

// audit-round5 fix #2 (CRIT): LongAdder.add / increment / decrement must be
// atomic. Round-7 HIGH-16: stripe across `LA_CELL_COUNT` cells so concurrent
// adders do not all CAS-spin on field 0. We optimistically try `base` once
// — if a CAS on `base` succeeds (uncontended path) we are done; otherwise
// we fall back to the stripe cell hashed to the current thread.
fn native_long_adder_add(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let x = match args.get(1) {
        Some(Value::Long(v)) => *v,
        _ => 0,
    };
    // Fast path: uncontended CAS on base.
    if let Some(base_slot) = striped64_base_slot(ctx, this) {
        let current = ctx.get_field_volatile(this, base_slot);
        let base = match current {
            Value::Long(v) => v,
            _ => 0,
        };
        let new_val = Value::Long(base.wrapping_add(x));
        if ctx.compare_and_swap_field(this, base_slot, current, new_val) {
            return Ok(None);
        }
    }
    // Contended path: stripe to a cell, do an uncontended atomic add.
    // `fetch_add` on `AtomicI64` is wait-free, no CAS-loop, no spinning.
    let idx = long_adder_stripe();
    let cells = long_adder_cells(ctx, this);
    cells.cells[idx].fetch_add(x, std::sync::atomic::Ordering::Relaxed);
    Ok(None)
}

fn native_long_adder_increment(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    if let Some(base_slot) = striped64_base_slot(ctx, this) {
        let current = ctx.get_field_volatile(this, base_slot);
        let base = match current {
            Value::Long(v) => v,
            _ => 0,
        };
        let new_val = Value::Long(base.wrapping_add(1));
        if ctx.compare_and_swap_field(this, base_slot, current, new_val) {
            return Ok(None);
        }
    }
    let idx = long_adder_stripe();
    let cells = long_adder_cells(ctx, this);
    cells.cells[idx].fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    Ok(None)
}

fn native_long_adder_decrement(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    if let Some(base_slot) = striped64_base_slot(ctx, this) {
        let current = ctx.get_field_volatile(this, base_slot);
        let base = match current {
            Value::Long(v) => v,
            _ => 0,
        };
        let new_val = Value::Long(base.wrapping_sub(1));
        if ctx.compare_and_swap_field(this, base_slot, current, new_val) {
            return Ok(None);
        }
    }
    let idx = long_adder_stripe();
    let cells = long_adder_cells(ctx, this);
    cells.cells[idx].fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
    Ok(None)
}

/// Sum the per-cell strip into a single i64. Caller adds `base` separately.
fn long_adder_cells_sum(ctx: &mut dyn NativeContext, this: ObjectRef) -> i64 {
    // Fast path: no cells allocated yet (init / never contended).
    let key = ctx.identity_hash_code(this);
    let t = long_adder_cells_table().lock();
    let Some(c) = t.get(&key).cloned() else {
        return 0;
    };
    drop(t);
    let mut s: i64 = 0;
    for cell in c.cells.iter() {
        s = s.wrapping_add(cell.load(std::sync::atomic::Ordering::Relaxed));
    }
    s
}

fn native_long_adder_sum(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Long(0))),
    };
    // audit-round5 fix #2 + round-7 HIGH-16: volatile read of the base
    // and a separate Relaxed sum across stripe cells. The JDK contract
    // allows `sum()` to return an "approximate" value if concurrent
    // updates race; we follow the same relaxation.
    let base = if let Some(base_slot) = striped64_base_slot(ctx, this) {
        match ctx.get_field_volatile(this, base_slot) {
            Value::Long(v) => v,
            _ => 0,
        }
    } else {
        0
    };
    let cells = long_adder_cells_sum(ctx, this);
    Ok(Some(Value::Long(base.wrapping_add(cells))))
}

fn native_long_adder_int_value(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    // Round-7 HIGH-16: must include stripe cells, otherwise `intValue` /
    // `(int)sum()` returns only the `base` and drops every contended add.
    let base = if let Some(base_slot) = striped64_base_slot(ctx, this) {
        match ctx.get_field(this, base_slot) {
            Value::Long(v) => v,
            _ => 0,
        }
    } else {
        0
    };
    let total = base.wrapping_add(long_adder_cells_sum(ctx, this));
    Ok(Some(Value::Int(total as i32)))
}

fn native_long_adder_reset(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    // audit-round5 fix #2: volatile store so other threads observing via
    // `sum`/`get_field_volatile` immediately see the cleared cell.
    if let Some(base_slot) = striped64_base_slot(ctx, this) {
        ctx.set_field_volatile(this, base_slot, Value::Long(0));
    }
    // Round-7 HIGH-16: also zero every stripe cell, otherwise contended
    // adds remain visible after `reset()`.
    let key = ctx.identity_hash_code(this);
    let t = long_adder_cells_table().lock();
    if let Some(c) = t.get(&key).cloned() {
        drop(t);
        for cell in c.cells.iter() {
            cell.store(0, std::sync::atomic::Ordering::Relaxed);
        }
    }
    Ok(None)
}

fn native_long_adder_sum_then_reset(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Long(0))),
    };
    // Round-7 HIGH-16: atomically swap `base` to 0 via CAS-loop, then
    // swap every stripe cell to 0 with `swap` (wait-free). The JDK
    // `sumThenReset` is documented as a non-atomic snapshot — concurrent
    // adds racing in the middle may be partly visible in the returned
    // value and partly survive into the reset table. We match that.
    let base = if let Some(base_slot) = striped64_base_slot(ctx, this) {
        loop {
            let current = ctx.get_field_volatile(this, base_slot);
            if ctx.compare_and_swap_field(this, base_slot, current, Value::Long(0)) {
                break match current {
                    Value::Long(v) => v,
                    _ => 0,
                };
            }
        }
    } else {
        0
    };
    let mut total = base;
    let key = ctx.identity_hash_code(this);
    let t = long_adder_cells_table().lock();
    if let Some(c) = t.get(&key).cloned() {
        drop(t);
        for cell in c.cells.iter() {
            let old = cell.swap(0, std::sync::atomic::Ordering::Relaxed);
            total = total.wrapping_add(old);
        }
    }
    Ok(Some(Value::Long(total)))
}

fn native_long_adder_to_string(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    // Round-7 HIGH-16: include the stripe cell sum so toString reports
    // the same value as `sum()`.
    let base = if let Some(base_slot) = striped64_base_slot(ctx, this) {
        match ctx.get_field(this, base_slot) {
            Value::Long(v) => v,
            _ => 0,
        }
    } else {
        0
    };
    let total = base.wrapping_add(long_adder_cells_sum(ctx, this));
    let s = ctx.create_string(&total.to_string());
    Ok(Some(Value::Object(Some(s))))
}

// --- DoubleAdder ---
fn native_double_adder_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    if let Some(base_slot) = striped64_base_slot(ctx, this) {
        ctx.set_field(this, base_slot, Value::Long(0));
    }
    Ok(None)
}

// audit-round5 fix #2 (CRIT, mirror): DoubleAdder.add must be atomic for
// the same reasons as LongAdder.add. CAS uses bit-pattern equality on
// Value::Double (see vm_exec::values_equal_for_cas) so NaN does not cause
// a livelock — `Double(NaN).to_bits() == Double(NaN).to_bits()` holds.
fn native_double_adder_add(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let x = match args.get(1) {
        Some(Value::Double(v)) => *v,
        _ => 0.0,
    };
    let Some(base_slot) = striped64_base_slot(ctx, this) else {
        return Ok(None);
    };
    loop {
        let current = ctx.get_field_volatile(this, base_slot);
        let old = match current {
            Value::Long(v) => f64::from_bits(v as u64),
            Value::Double(v) => v,
            _ => 0.0,
        };
        let new_val = Value::Long((old + x).to_bits() as i64);
        if ctx.compare_and_swap_field(this, base_slot, current, new_val) {
            return Ok(None);
        }
    }
}

fn native_double_adder_sum(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Double(0.0))),
    };
    // audit-round5 fix #2: volatile read so concurrent `add`s are observed.
    let sum = striped64_base_slot(ctx, this)
        .and_then(|base_slot| match ctx.get_field_volatile(this, base_slot) {
            Value::Long(v) => Some(f64::from_bits(v as u64)),
            Value::Double(v) => Some(v),
            _ => None,
        })
        .unwrap_or(0.0);
    Ok(Some(Value::Double(sum)))
}

fn native_double_adder_reset(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    // audit-round5 fix #2: volatile store so other threads' `sum`
    // reads the cleared value immediately.
    if let Some(base_slot) = striped64_base_slot(ctx, this) {
        ctx.set_field_volatile(this, base_slot, Value::Long(0));
    }
    Ok(None)
}

