fn native_array_get_float(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let arr = reflect_array_arg(ctx, args)?;
    let idx = reflect_array_index(&*ctx, arr, args)?;
    Ok(Some(ctx.get_array_element(arr, idx)))
}

fn native_array_set_float(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let arr = reflect_array_arg(ctx, args)?;
    let idx = reflect_array_index(&*ctx, arr, args)?;
    let val = args.get(2).cloned().unwrap_or(Value::Float(0.0));
    ctx.set_array_element(arr, idx, val);
    Ok(None)
}

fn native_array_get_double(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let arr = reflect_array_arg(ctx, args)?;
    let idx = reflect_array_index(&*ctx, arr, args)?;
    Ok(Some(ctx.get_array_element(arr, idx)))
}

fn native_array_set_double(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let arr = reflect_array_arg(ctx, args)?;
    let idx = reflect_array_index(&*ctx, arr, args)?;
    let val = args.get(2).cloned().unwrap_or(Value::Double(0.0));
    ctx.set_array_element(arr, idx, val);
    Ok(None)
}

fn array_new_instance_component(
    ctx: &mut dyn NativeContext,
    mirror_arg: Option<&Value>,
) -> (String, Option<cratonvm_types::ClassId>) {
    match mirror_arg {
        Some(Value::Object(Some(mirror))) => {
            // Preserve the exact ClassId when the mirror represents a class
            // from an isolated defining loader. The name is still needed for
            // primitive handling and for the legacy fallback, but name-only
            // resolution is invalid for same-named classes from distinct
            // loaders (the AOT forked-loader case).
            let component_id = crate::lang_class::mirror_class_id(&*ctx, *mirror);
            let component_name = crate::lang_class::mirror_class_name(&*ctx, *mirror)
                .filter(|s| !s.is_empty())
                .or_else(|| ctx.read_string(*mirror))
                .map(|s| s.replace('.', "/"))
                .unwrap_or_else(|| "java/lang/Object".to_string());
            (component_name, component_id)
        }
        _ => ("java/lang/Object".to_string(), None),
    }
}

fn array_new_instance_for_component(
    ctx: &mut dyn NativeContext,
    comp_name: &str,
    component_id: Option<cratonvm_types::ClassId>,
    length: usize,
) -> cratonvm_types::ObjectRef {
    use cratonvm_types::ArrayElementType;
    match comp_name {
        "int" | "I" => ctx.new_array(ArrayElementType::Int, length),
        "long" | "J" => ctx.new_array(ArrayElementType::Long, length),
        "float" | "F" => ctx.new_array(ArrayElementType::Float, length),
        "double" | "D" => ctx.new_array(ArrayElementType::Double, length),
        "boolean" | "Z" => ctx.new_array(ArrayElementType::Boolean, length),
        "byte" | "B" => ctx.new_array(ArrayElementType::Byte, length),
        "char" | "C" => ctx.new_array(ArrayElementType::Char, length),
        "short" | "S" => ctx.new_array(ArrayElementType::Short, length),
        _ => {
            let comp_id = component_id.unwrap_or_else(|| {
                ctx.ensure_class_initialized(comp_name)
                    .unwrap_or(cratonvm_types::ClassId::new(0))
            });
            if dbg_toarray_enabled() {
                eprintln!(
                    "[DBG_TOARRAY] Array.newInstance comp_name={:?} comp_id={:?} len={}",
                    comp_name, comp_id, length
                );
            }
            ctx.new_ref_array(comp_id, length)
        }
    }
}

/// The three `Array.newInstance(Class, ...)` argument checks HotSpot makes
/// before it allocates anything, measured on Temurin 25:
///
/// ```text
/// Array.newInstance(null, 1)            NullPointerException
/// Array.newInstance(void.class, 1)      IllegalArgumentException (null message)
/// Array.newInstance(int.class, new int[0])  IllegalArgumentException (null message)
/// ```
///
/// All three used to allocate and return an array instead — a null component
/// type quietly became `Object[]`, and `void.class` did too.
fn reflect_array_component_ok(
    ctx: &mut dyn NativeContext,
    mirror_arg: Option<&Value>,
) -> Result<(), MethodCallFailed> {
    let mirror = match mirror_arg {
        Some(Value::Object(Some(m))) => *m,
        // A null `Class` argument. HotSpot dereferences it, so: NPE, no message.
        _ => return Err(RuntimeError::NullPointerException { message: None }.into()),
    };
    let name = crate::lang_class::mirror_class_name(&*ctx, mirror).unwrap_or_default();
    if name == "void" {
        // There is no `void[]`. Empty message = null `getMessage()`.
        return Err(RuntimeError::IllegalArgumentException {
            message: String::new(),
        }
        .into());
    }
    Ok(())
}

fn native_array_new_instance(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    reflect_array_component_ok(ctx, args.first())?;
    // `.max(0)` CLAMPED a negative length and returned an empty array, so
    // `Array.newInstance(int.class, -1)` handed back an `int[0]` where HotSpot
    // throws. Measured on Temurin 25: `NegativeArraySizeException` whose detail
    // message is the size alone, with no prose — the same text `new int[-1]`
    // produces, which is why the variant builds it from the payload rather than
    // taking a string. Same shape as the missing bounds check on the accessors:
    // an out-of-range argument silently accepted.
    let len = match args.get(1) {
        Some(Value::Int(v)) if *v < 0 => {
            return Err(RuntimeError::NegativeArraySizeException { size: *v }.into());
        }
        Some(Value::Int(v)) => *v as usize,
        _ => 0,
    };
    let (comp_name, component_id) = array_new_instance_component(ctx, args.first());
    let arr = array_new_instance_for_component(ctx, &comp_name, component_id, len);
    Ok(Some(Value::Object(Some(arr))))
}

fn native_array_new_instance_multi(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    reflect_array_component_ok(ctx, args.first())?;
    // Zero dimensions is not a zero-length array, it is a bad argument.
    if let Some(Value::Object(Some(dims))) = args.get(1) {
        if ctx.array_length(*dims) == 0 {
            return Err(RuntimeError::IllegalArgumentException {
                message: String::new(),
            }
            .into());
        }
    }
    // `Array.newInstance(Class, int[])` must fully materialize ALL dimensions
    // with the precise nested array type (`String[2][2]` → `[[Ljava/lang/String;`).
    // The previous body read only `dims[0]` and built a one-dimensional array,
    // collapsing e.g. `new String[2][2]` to `String[]`
    // (SpEL ArrayConstructorTests.multiDimensionalArrays). Delegate to the
    // shared nested-array builder, which also backs `Array.multiNewArray`.
    lang_system::native_array_multi_new_array(ctx, args)
}

// ===========================================================================
// Phase 47: java.lang.reflect.Proxy — dynamic proxy stubs
// ===========================================================================
//
// WP2.5 (Strategy B+): every proxy still lands on the single synthetic
// class `java/lang/reflect/Proxy$Instance`, but per-proxy data
// (interfaces array, handler) is now stored in dedicated slots and the
// natives expose helpers so reflection round-trips work.
//
// The globals below back `Class.getInterfaces()` on the proxy class
// mirror — see the doc-comment on `vm::runtime::proxy::last_interfaces`
// for the rationale and the known multi-threaded-creation limitation.

// bug nb-lib-gckeys §2: the last-proxy interfaces array is no longer stored
// here as a raw `AtomicU64` pointer (which was never a GC root and could
// dangle after a moving collection). It now lives as a GC-tracked `ObjectRef`
// in `lang_class` (`set_proxy_last_interfaces` / `proxy_last_interfaces`),
// rooted and remapped by the annotation-proxy GC hooks. The
// `proxy_last_interfaces_bits()` accessor below is retained for the WP2.5
// white-box test and now derives from that GC-tracked cell.

/// Total proxies created in this process. Diagnostic only.
static PROXY_INSTANCES_CREATED: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// WP2.5-B — generated-proxy-class cache, keyed on
/// `(vm_identity, loader_id, ordered_iface_class_ids)`. One generated
/// `$ProxyN` class per (VM, loader, ordered-interface-list) — the JDK
/// `ProxyGenerator` does the same minus the VM, keying on interface order so
/// `getInterfaces()` round-trips the user-requested order.
///
/// The `vm_identity` is load-bearing, not hygiene. Every other component of
/// this entry is a per-VM number: `loader_id` is a small per-VM integer, the
/// key's `ClassId`s are minted per VM from zero, and **the VALUE is a
/// `ClassId`** — a handle that means nothing outside the class manager that
/// issued it. Without the partition, VM B asking for a proxy over its
/// interface `ClassId(42)` hit VM A's entry and was handed VM A's generated
/// `$ProxyN` id. `class_name_of_id` then answered `None` for it, which is the
/// `?` in the `ClassCastException: ? cannot be cast to …` that made the
/// proxy/annotation corpus tests flip in roughly half of all parallel runs —
/// in both directions, since the borrowed id sometimes happened to satisfy
/// the cast and sometimes not.
static PROXY_CLASS_CACHE: parking_lot::RwLock<
    Option<
        rustc_hash::FxHashMap<(usize, u32, Vec<cratonvm_types::ClassId>), cratonvm_types::ClassId>,
    >,
> = parking_lot::RwLock::new(None);

/// Drop every generated-proxy-class row this VM's class unloading just
/// invalidated.
///
/// A row is `(vm, loader_namespace, ordered_iface_ids) -> generated_class_id`,
/// and **class unloading can kill either side**. The value goes first: once
/// `ClassManager::unload_user_classes` has removed the generated `$ProxyN`,
/// a later `Proxy.newProxyInstance` with the same key was handed the dead id
/// straight back out of this cache and allocated an instance against it. Its
/// class then resolves to nothing — the same
/// `ClassCastException: ? cannot be cast to …` this cache's `vm_identity`
/// partition was added to stop, reached the other way round. That is what made
/// `BatchJdbcAutoConfigurationTests`, `FreeMarkerAutoConfigurationReactive-
/// IntegrationTests` and `OpenTelemetrySdkAutoConfigurationTests` fail under
/// `-XX:+UseZGC`, whose every collection is a full mark and therefore runs
/// loader reclamation on every cycle rather than only in the generational
/// collector's narrow full-mark windows.
///
/// The KEY is purged on the same evidence: an entry keyed on an interface
/// `ClassId` that no longer exists cannot be matched by a live request except
/// by id reuse, and matching it by reuse is precisely the bug above.
pub fn forget_unloaded_proxy_classes(vm_identity: usize, class_ids: &[u32]) {
    if class_ids.is_empty() {
        return;
    }
    let dead: rustc_hash::FxHashSet<u32> = class_ids.iter().copied().collect();
    let mut guard = PROXY_CLASS_CACHE.write();
    if let Some(map) = guard.as_mut() {
        map.retain(|(vm, _, ifaces), cid| {
            *vm != vm_identity
                || (!dead.contains(&cid.as_u32())
                    && !ifaces.iter().any(|i| dead.contains(&i.as_u32())))
        });
    }
}

/// Drop every generated-proxy-class row belonging to `vm_identity`. Called
/// from `release_vm_native_state`; the rows hold `ClassId`s into a class
/// manager that is going away.
pub fn forget_vm_proxy_classes(vm_identity: usize) {
    let mut guard = PROXY_CLASS_CACHE.write();
    if let Some(map) = guard.as_mut() {
        map.retain(|(vm, _, _), _| *vm != vm_identity);
    }
    let mut modules = PROXY_LOADER_MODULES.write();
    if let Some(map) = modules.as_mut() {
        map.retain(|(vm, _), _| *vm != vm_identity);
    }
}

#[cfg(test)]
mod proxy_class_cache_unload_tests {
    use cratonvm_types::ClassId;

    /// The row whose VALUE was unloaded must go: handing that `ClassId` back
    /// out of the cache is what allocated an instance against a class the
    /// class manager had already removed.
    #[test]
    fn an_unloaded_generated_proxy_class_is_dropped_from_the_cache() {
        const VM: usize = 0xC0FFEE;
        {
            let mut guard = super::PROXY_CLASS_CACHE.write();
            let map = guard.get_or_insert_with(rustc_hash::FxHashMap::default);
            map.insert((VM, 7, vec![ClassId::new(100)]), ClassId::new(3003));
            map.insert((VM, 7, vec![ClassId::new(101)]), ClassId::new(3005));
        }
        super::forget_unloaded_proxy_classes(VM, &[3003]);
        let guard = super::PROXY_CLASS_CACHE.read();
        let map = guard.as_ref().expect("cache populated above");
        assert!(map.get(&(VM, 7, vec![ClassId::new(100)])).is_none());
        assert_eq!(
            map.get(&(VM, 7, vec![ClassId::new(101)])),
            Some(&ClassId::new(3005)),
            "a live row must survive the purge",
        );
    }

    /// And the row whose KEY names an unloaded interface: it can only be
    /// matched again through `ClassId` reuse, and matching by reuse is the
    /// same defect one step removed.
    #[test]
    fn a_row_keyed_on_an_unloaded_interface_is_dropped_too() {
        const VM: usize = 0xC0FFEF;
        {
            let mut guard = super::PROXY_CLASS_CACHE.write();
            let map = guard.get_or_insert_with(rustc_hash::FxHashMap::default);
            map.insert(
                (VM, 9, vec![ClassId::new(200), ClassId::new(201)]),
                ClassId::new(4000),
            );
        }
        super::forget_unloaded_proxy_classes(VM, &[201]);
        let guard = super::PROXY_CLASS_CACHE.read();
        let map = guard.as_ref().expect("cache populated above");
        assert!(map
            .get(&(VM, 9, vec![ClassId::new(200), ClassId::new(201)]))
            .is_none());
    }

    /// Another VM's rows are none of this VM's business — the same partition
    /// the `vm_identity` key component exists to keep.
    #[test]
    fn another_vms_rows_are_untouched() {
        const MINE: usize = 0xD0D0;
        const THEIRS: usize = 0xE0E0;
        {
            let mut guard = super::PROXY_CLASS_CACHE.write();
            let map = guard.get_or_insert_with(rustc_hash::FxHashMap::default);
            map.insert((THEIRS, 1, vec![ClassId::new(300)]), ClassId::new(5000));
        }
        super::forget_unloaded_proxy_classes(MINE, &[5000, 300]);
        let guard = super::PROXY_CLASS_CACHE.read();
        let map = guard.as_ref().expect("cache populated above");
        assert_eq!(
            map.get(&(THEIRS, 1, vec![ClassId::new(300)])),
            Some(&ClassId::new(5000)),
        );
    }
}

/// WP2.5-B — global counter for the `$ProxyN` suffix. JDK uses
/// per-loader counters; a global counter is sufficient here since the
/// generated names are internal and never observed by user code other
/// than via `Class.getName()`.
static PROXY_CLASS_COUNTER: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);

/// proxy-real-classfile increment 7 — per-loader dynamic-module sequence number
/// backing the generated proxy package `jdk/proxyN/$ProxyM`, mirroring HotSpot's
/// per-loader dynamic `jdk.proxyN` module (one module per class loader, `N`
/// assigned in first-encounter order starting at 1; `$ProxyM` keeps using the
/// global [`PROXY_CLASS_COUNTER`]). Public-interface proxies of the SAME loader
/// share one `jdk/proxyN` package, exactly like the JDK's `ProxyBuilder`.
static PROXY_MODULE_COUNTER: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);
/// Keyed by `(vm_identity, loader_id)`: loader ids are small per-VM integers,
/// so an unqualified key let VM B's loader 2 inherit VM A's module number and
/// generate its `$ProxyN` into a package that VM A had already claimed.
static PROXY_LOADER_MODULES: parking_lot::RwLock<Option<rustc_hash::FxHashMap<(usize, u32), u32>>> =
    parking_lot::RwLock::new(None);

/// WP2.5 v3 item 6 — classify a thrown exception from
/// `InvocationHandler.invoke` against the proxied method's declared
/// throws set; wrap in `java.lang.reflect.UndeclaredThrowableException`
/// if not a `RuntimeException` / `Error` and not declared.
///
/// On any failure to allocate or invoke the wrapper ctor, the original
/// exception is returned verbatim — losing the wrap is preferable to
/// losing the exception entirely.
fn wrap_undeclared_throwable(
    ctx: &mut dyn NativeContext,
    method_obj: cratonvm_types::ObjectRef,
    thrown: cratonvm_types::ObjectRef,
) -> cratonvm_types::ObjectRef {
    // 1) RuntimeException / Error — always propagate.
    let thrown_cid = ctx.class_id_of_object(thrown);
    if crate::nbflags().dbg_ute {
        let thrown_name = ctx
            .class_name_of_id(thrown_cid)
            .unwrap_or_else(|| "<unknown>".to_string());
        let method_name = match ctx.get_field_by_name(method_obj, "name") {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        let decl_class = match ctx.get_field_by_name(method_obj, "clazz") {
            Value::Object(Some(m)) => ctx
                .class_id_from_mirror(m)
                .and_then(|c| ctx.class_name_of_id(c))
                .unwrap_or_else(|| "<unknown>".to_string()),
            _ => "<unknown>".to_string(),
        };
        eprintln!(
            "[DBG_UTE] method={}.{} thrown={}",
            decl_class, method_name, thrown_name
        );
    }
    if let Ok(rcid) = ctx.ensure_class_initialized("java/lang/RuntimeException") {
        if thrown_cid == rcid || ctx.is_subclass(thrown_cid, rcid) {
            return thrown;
        }
    }
    if let Ok(ecid) = ctx.ensure_class_initialized("java/lang/Error") {
        if thrown_cid == ecid || ctx.is_subclass(thrown_cid, ecid) {
            return thrown;
        }
    }

    // 2) Inspect Method.exceptionTypes (Class[]). Generated `<clinit>`
    // populates this via `Class.getExceptionTypes()`; if for any reason
    // the field is missing or null, fall through to the wrap path —
    // matching JDK behaviour for methods with no declared throws.
    if let Value::Object(Some(arr)) = ctx.get_field_by_name(method_obj, "exceptionTypes") {
        let n = ctx.array_length(arr);
        for i in 0..n {
            if let Value::Object(Some(decl_mirror)) = ctx.get_array_element(arr, i) {
                if let Some(decl_cid) = ctx.class_id_from_mirror(decl_mirror) {
                    if thrown_cid == decl_cid || ctx.is_subclass(thrown_cid, decl_cid) {
                        return thrown;
                    }
                }
            }
        }
    }

    // 3) Wrap. Allocate UndeclaredThrowableException and invoke its
    // (Throwable) constructor.
    let ute_cid =
        match ctx.ensure_class_initialized("java/lang/reflect/UndeclaredThrowableException") {
            Ok(c) => c,
            Err(_) => return thrown,
        };
    let n_fields = ctx.class_num_total_fields(ute_cid).max(4);
    let ute = ctx.alloc_object(ute_cid, n_fields);
    let ctor_args = [Value::Object(Some(ute)), Value::Object(Some(thrown))];
    let _ = ctx.invoke(
        "java/lang/reflect/UndeclaredThrowableException",
        "<init>",
        "(Ljava/lang/Throwable;)V",
        &ctor_args,
    );
    ute
}

/// proxy-real-classfile increment 6 — `InvocationHandler.invokeDefault(Object
/// proxy, Method method, Object... args)` (JDK 16+, a `static` interface
/// method).
///
/// The real JDK body drives `Proxy.invokeDefault`, which reflects the generated
/// proxy class's `proxyClassLookup` accessor + a full-power
/// `MethodHandles.Lookup` to bind an `invokespecial` MethodHandle to the
/// interface's default body. CratonVM's generated `$ProxyN` emits no
/// `proxyClassLookup` accessor (and the proxy model has no real per-class
/// Lookup), so the real bytecode throws
/// `InternalError: NoSuchMethodException: proxyClassLookup`. This native is
/// force-dispatched over the real bytecode (see
/// `interpreter::force_native_over_real_jdk_bytecode`) and runs the default body
/// directly via [`NativeContext::invoke_special`] — the same super-call dispatch
/// (`Lookup.findSpecial` semantics) the JDK ultimately performs, minus the
/// Lookup plumbing. Nested *virtual* calls on the proxy inside the default body
/// still route back through the `InvocationHandler` (invoke_special only
/// bypasses the retarget for the single *resolved* method).
///
/// Args (static method): `[0]` proxy, `[1]` `Method`, `[2]` `Object[]` args
/// (may be `null` for a no-arg default method).
fn native_invocation_handler_invoke_default(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    use cratonvm_types::error::RuntimeError;

    let proxy = match args.first() {
        Some(Value::Object(Some(p))) => *p,
        _ => {
            return Err(RuntimeError::NullPointerException {
                message: Some("InvocationHandler.invokeDefault: proxy is null".to_string()),
            }
            .into());
        }
    };
    let method_obj = match args.get(1) {
        Some(Value::Object(Some(m))) => *m,
        _ => {
            return Err(RuntimeError::NullPointerException {
                message: Some("InvocationHandler.invokeDefault: method is null".to_string()),
            }
            .into());
        }
    };

    // JDK contract: the receiver must be a proxy instance.
    if !proxy_chain_reaches_instance(ctx, ctx.class_id_of_object(proxy)) {
        return Err(RuntimeError::IllegalArgumentException {
            message: "'proxy' is not a proxy instance".to_string(),
        }
        .into());
    }

    // JDK contract: the method must be a default method — public, non-abstract,
    // non-static, declared on an interface (mirrors `Method.isDefault()`).
    const ACC_PUBLIC: i32 = 0x0001;
    const ACC_STATIC: i32 = 0x0008;
    const ACC_ABSTRACT: i32 = 0x0400;
    let modifiers = match ctx.get_field_by_name(method_obj, "modifiers") {
        Value::Int(v) => v,
        _ => 0,
    };
    let declaring_mirror = match ctx.get_field_by_name(method_obj, "clazz") {
        Value::Object(Some(m)) => m,
        _ => {
            return Err(RuntimeError::IllegalArgumentException {
                message: "InvocationHandler.invokeDefault: method has no declaring class"
                    .to_string(),
            }
            .into());
        }
    };
    let decl_is_interface = ctx
        .class_id_from_mirror(declaring_mirror)
        .map(|cid| ctx.is_interface_class(cid))
        .unwrap_or(false);
    let is_default =
        decl_is_interface && (modifiers & (ACC_ABSTRACT | ACC_PUBLIC | ACC_STATIC)) == ACC_PUBLIC;
    if !is_default {
        return Err(RuntimeError::IllegalArgumentException {
            message: "method is not a default method".to_string(),
        }
        .into());
    }

    let iface_name = match crate::lang_class::mirror_class_name(ctx, declaring_mirror) {
        Some(n) => n,
        None => {
            return Err(RuntimeError::IllegalArgumentException {
                message: "InvocationHandler.invokeDefault: cannot resolve declaring interface"
                    .to_string(),
            }
            .into());
        }
    };
    let method_name = match ctx.get_field_by_name(method_obj, "name") {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let descriptor = crate::lang_class::method_descriptor_for_invoke(ctx, method_obj);
    let (param_descs, ret_desc) = crate::lang_class::parse_descriptor_param_and_return(&descriptor);

    // Unbox the `Object[]` args to match the default method's primitive /
    // reference parameter types, prepending the proxy receiver (which is
    // `invoke_special`'s `args[0]`).
    let args_arr = match args.get(2) {
        Some(Value::Object(Some(a))) => Some(*a),
        _ => None,
    };
    let supplied = match args_arr {
        Some(a) => ctx.array_length(a),
        None => 0,
    };
    if supplied != param_descs.len() {
        return Err(RuntimeError::IllegalArgumentException {
            message: format!(
                "InvocationHandler.invokeDefault: wrong number of arguments for {}.{}: \
                 expected {}, got {}",
                iface_name,
                method_name,
                param_descs.len(),
                supplied
            ),
        }
        .into());
    }
    let mut invoke_args: Vec<Value> = Vec::with_capacity(param_descs.len() + 1);
    invoke_args.push(Value::Object(Some(proxy)));
    for (i, pdesc) in param_descs.iter().enumerate() {
        let raw = match args_arr {
            Some(a) => ctx.get_array_element(a, i),
            None => Value::Object(None),
        };
        invoke_args.push(crate::lang_class::unbox_arg(ctx, raw, pdesc));
    }

    // Run the interface's default body as an invokespecial super-call — exactly
    // `I.m(...)`, with no virtual retarget back to the proxy's intercepted
    // dispatch. A thrown exception propagates verbatim (invokeDefault declares
    // `throws Throwable`; it does NOT apply UndeclaredThrowableException
    // wrapping — that is only on the proxy-method dispatch path).
    let result = ctx.invoke_special(&iface_name, &method_name, &descriptor, &invoke_args)?;

    // `invokeDefault` returns `Object` — box a primitive result per the return
    // type; reference / void results pass through unchanged.
    match result {
        Some(val) => Ok(Some(crate::lang_class::box_value(ctx, val, &ret_desc))),
        None => Ok(Some(Value::Object(None))),
    }
}

/// real-cdi-bean-container — Agroal datasource shim gate (Keycloak Gap 8).
///
/// When ON, the `agroal_pool.rs` native shim is **not** registered, so
/// Quarkus/Keycloak run the **real** `io.agroal.pool.DataSource` /
/// `ConnectionPool` / `AgroalDataSourceConfigurationSupplier` bytecode over the
/// (working) real `org.h2.Driver`. The shim's
/// `AgroalDataSourceConfigurationSupplier.get()` native returns a synthetic
/// object typed as the bare interface `AgroalDataSourceConfiguration` (no
/// method bodies); the real downstream `DataSourceProvider.getDataSource`
/// bytecode then does `invokeinterface config.dataSourceImplementation()` and
/// hits the abstract method → `AbstractMethodError`. So the shim and the real
/// container bytecode are mutually exclusive on this path.
///
/// Currently **opt-in** (`CRATONVM_REAL_AGROAL=1`), default = the legacy shim,
/// while the real pool's concurrency (housekeeping executor + AQS synchronizer)
/// is being validated. Once the real path is green by default this flips to
/// opt-out (`CRATONVM_SYNTHETIC_AGROAL`), mirroring the AQS / Spring-startup
/// precedents.
pub fn real_agroal() -> bool {
    crate::nbflags().real_agroal && !crate::nbflags().synthetic_agroal
}

/// Vert.x / Netty event loop (Keycloak Gap 9). Under `CRATONVM_REAL_VERTX` the
/// synthetic `vertx_eventloop` natives (`VertxImpl.init`, `NioEventLoop.run` /
/// `execute` / `schedule` / ...) are suppressed so the REAL Netty
/// `NioEventLoopGroup` / `SingleThreadEventExecutor` / `NioEventLoop.run()`
/// bytecode runs, driving `Selector.select()` over CratonVM's own selector (see
/// the `WEPollSelectorProvider` routing in `native-io`). The synthetic loop runs
/// only tasks/timers and does NOT poll the selector, so a real Vert.x HTTP server
/// binds but never accepts. Opt-in while the real path is validated; flips to
/// opt-out (`CRATONVM_SYNTHETIC_VERTX`) once green by default, mirroring `real_agroal`.
pub fn real_vertx() -> bool {
    crate::nbflags().real_vertx && !crate::nbflags().synthetic_vertx
}

/// Outcome of [`define_or_get_proxy_class`]. Distinguishes the *intended*
/// gate-off degrade (use the synthetic shim) from a *genuine* generation
/// failure, so STRICT mode ([`real_proxy_strict`]) can surface the latter as a
/// real JDK exception rather than masking it with the shim.
enum ProxyClassOutcome {
    /// The real generated `$ProxyN` class (canonical path).
    Real(cratonvm_types::ClassId),
    /// `CRATONVM_REAL_PROXY=0` — the synthetic shim is the intended path.
    Degrade,
    /// A concrete spec/emit/define failure. `&'static str` is the stage, for
    /// the exception message + the `CRATONVM_DBG_PROXY` audit.
    Failed(&'static str),
}

/// WP2.5 v3 — parse a JVMS method descriptor's parameter list into
/// internal class names. Primitives map to their wrapper internal
/// names (the emitter then rewrites those to `<Wrapper>.TYPE` GETSTATIC
/// so `Class.getMethod` matches the primitive `Class<?>`).
///
///   `I` → `java/lang/Integer`         `J` → `java/lang/Long`
///   `Z` → `java/lang/Boolean`         `F` → `java/lang/Float`
///   `B` → `java/lang/Byte`            `D` → `java/lang/Double`
///   `C` → `java/lang/Character`
///   `S` → `java/lang/Short`
///   `Lfoo/Bar;`     → `foo/Bar`       (plain reference)
///   `[I`            → `[I`            (array — kept as descriptor)
///   `[[Lfoo/Bar;`   → `[[Lfoo/Bar;`
fn parse_param_class_names(descriptor: &str) -> Vec<String> {
    let mut out = Vec::new();
    let bytes = descriptor.as_bytes();
    let mut i = match bytes.first() {
        Some(b'(') => 1,
        _ => return out,
    };
    while i < bytes.len() && bytes[i] != b')' {
        let start = i;
        while i < bytes.len() && bytes[i] == b'[' {
            i += 1;
        }
        if i >= bytes.len() {
            break;
        }
        match bytes[i] {
            b'L' => {
                let name_start = i + 1;
                while i < bytes.len() && bytes[i] != b';' {
                    i += 1;
                }
                if i >= bytes.len() {
                    break;
                }
                if start == name_start - 1 {
                    out.push(descriptor[name_start..i].to_string());
                } else {
                    out.push(descriptor[start..=i].to_string());
                }
                i += 1;
            }
            b'I' | b'Z' | b'B' | b'C' | b'S' | b'J' | b'F' | b'D' => {
                if start == i {
                    let wrapper = match bytes[i] {
                        b'I' => "java/lang/Integer",
                        b'Z' => "java/lang/Boolean",
                        b'B' => "java/lang/Byte",
                        b'C' => "java/lang/Character",
                        b'S' => "java/lang/Short",
                        b'J' => "java/lang/Long",
                        b'F' => "java/lang/Float",
                        b'D' => "java/lang/Double",
                        _ => unreachable!(),
                    };
                    out.push(wrapper.to_string());
                } else {
                    out.push(descriptor[start..=i].to_string());
                }
                i += 1;
            }
            _ => {
                i += 1;
            }
        }
    }
    out
}

// ===========================================================================
// Phases 49-50: Enterprise Final — AtomicBoolean, Modifier extras, Class extras,
// CompletableFuture, Executors, Formatter
// ===========================================================================

fn register_enterprise_final_natives(registry: &mut NativeMethodRegistry) {
    // --- AtomicBoolean (1-field synthetic: value=0 Int) ---
    register_atomic_boolean_natives(registry);

    // --- AtomicStampedReference (2-field: ref=0, stamp=1) ---
    register_atomic_stamped_ref_natives(registry);

    // --- AtomicMarkableReference (2-field: ref=0, mark=1) ---
    register_atomic_markable_ref_natives(registry);

    // --- Modifier extras (remaining bit checks) ---
    let m = "java/lang/reflect/Modifier";
    registry.register(m, "isSynchronized", "(I)Z", native_modifier_is_synchronized);
    registry.register(m, "isVolatile", "(I)Z", native_modifier_is_volatile);
    registry.register(m, "isTransient", "(I)Z", native_modifier_is_transient);
    registry.register(m, "isNative", "(I)Z", native_modifier_is_native);
    registry.register(m, "isInterface", "(I)Z", native_modifier_is_interface);
    registry.register(m, "isStrict", "(I)Z", native_modifier_is_strict);
    registry.register(
        m,
        "toString",
        "(I)Ljava/lang/String;",
        native_modifier_to_string,
    );
    registry.register(m, "classModifiers", "()I", native_modifier_class_modifiers);
    registry.register(
        m,
        "interfaceModifiers",
        "()I",
        native_modifier_interface_modifiers,
    );
    registry.register(m, "fieldModifiers", "()I", native_modifier_field_modifiers);
    registry.register(
        m,
        "methodModifiers",
        "()I",
        native_modifier_method_modifiers,
    );
    registry.register(
        m,
        "constructorModifiers",
        "()I",
        native_modifier_constructor_modifiers,
    );

    // --- Class extras (additional methods not already registered) ---
    let c = "java/lang/Class";
    registry.register(
        c,
        "getComponentType",
        "()Ljava/lang/Class;",
        native_class_get_component_type,
    );
    registry.register(
        c,
        "componentType",
        "()Ljava/lang/Class;",
        native_class_get_component_type,
    );
    registry.register(
        c,
        "getPackageName",
        "()Ljava/lang/String;",
        native_class_get_package_name,
    );
    // T19_H10_GET_PACKAGE: real `Class.getPackage()` — synthesises a
    // `java.lang.Package` whose `name`, `implementation*`, and
    // `specification*` fields are populated from the class's source jar
    // manifest. Was `native_return_null`, which broke any code that did
    // `Foo.class.getPackage().getImplementationVersion()` on `<clinit>`.
    registry.register(
        c,
        "getPackage",
        "()Ljava/lang/Package;",
        native_class_get_package,
    );

    // T19_H11 — moved to `register_essential_natives` so the override
    // is active in real-JDK mode (this `register_synthetic_overrides`
    // function is only called under the `synthetic-jdk` feature gate).
    registry.register(c, "isEnum", "()Z", native_class_is_enum);
    registry.register(c, "isRecord", "()Z", native_class_is_record);
    registry.register(c, "isSealed", "()Z", native_class_is_sealed);
    registry.register(c, "isSynthetic", "()Z", native_class_is_synthetic);
    // The nesting predicates are derived from the class's own `InnerClasses`
    // entry (see `lang_class::class_nesting_kind`). They were `native_return_false`,
    // so under `synthetic-jdk` every nested class reported itself top-level —
    // `isMemberClass()` in particular is false for NO nested class on HotSpot.
    // Real-JDK mode never reaches here: it runs `java.lang.Class`'s own
    // bytecode, which was already correct on all 19 shapes of the
    // nesting/enclosing differential probe.
    registry.register(
        c,
        "isAnonymousClass",
        "()Z",
        native_class_is_anonymous_class,
    );
    registry.register(c, "isLocalClass", "()Z", native_class_is_local_class);
    registry.register(c, "isMemberClass", "()Z", native_class_is_member_class);
    // NEW-8: Class.isHidden real impl — was native_return_false which
    // shadowed the registration at lib.rs:~325. Both now consult the
    // class's hidden flag through NativeContext::is_class_hidden.
    registry.register(c, "isHidden", "()Z", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Int(0))),
        };
        let hidden = match lang_class::mirror_class_id(ctx, this) {
            // Lambda proxies (id >= 0x8000_0000) are JVM hidden classes in HotSpot
            // (JDK 15+). Reporting them as hidden makes `Class.getCanonicalName()`
            // return null (matching HotSpot) instead of leaking the synthesized
            // lambda name. bug-06 fam5 #1.
            Some(cid) if cid.as_u32() >= 0x8000_0000 && ctx.lambda_proxy_host(cid).is_some() => {
                true
            }
            Some(cid) => ctx.is_class_hidden(cid),
            None => false,
        };
        Ok(Some(Value::Int(if hidden { 1 } else { 0 })))
    });
    registry.register(
        c,
        "getCanonicalName",
        "()Ljava/lang/String;",
        native_class_get_canonical_name,
    );
    registry.register(
        c,
        "getTypeName",
        "()Ljava/lang/String;",
        native_class_get_type_name,
    );
    // WP2.1-class-modern: route the public `getEnclosing*` accessors to
    // their real impls in `lang_reflect`. Previously these were
    // `native_return_null` — fine for "doesn't crash" but breaks
    // ByteBuddy / Hibernate scanners that rely on
    // `Inner.class.getEnclosingClass() == Outer.class`.
    // The proper natives consult the InnerClasses / EnclosingMethod
    // attributes via `NativeContext::inner_classes` / `enclosing_method`
    // (see `native_class_get_enclosing_class` in lang_reflect.rs:205).
    //
    // `register_wp2_1_natives` (called inside `register_essential_natives`)
    // installs these earlier; the assignments here would clobber them
    // back to null-stubs because `register_synthetic_overrides` runs
    // *after* essential. Keep both consistent.
    registry.register(
        c,
        "getEnclosingClass",
        "()Ljava/lang/Class;",
        lang_reflect::native_class_get_enclosing_class,
    );
    registry.register(
        c,
        "getEnclosingMethod",
        "()Ljava/lang/reflect/Method;",
        lang_reflect::native_class_get_enclosing_method_public,
    );
    registry.register(
        c,
        "getEnclosingConstructor",
        "()Ljava/lang/reflect/Constructor;",
        lang_reflect::native_class_get_enclosing_constructor_public,
    );
    registry.register(
        c,
        "getDeclaringClass",
        "()Ljava/lang/Class;",
        lang_class::native_class_get_declaring_class,
    );
    registry.register(
        c,
        "getNestHost",
        "()Ljava/lang/Class;",
        native_class_get_nest_host,
    );
    registry.register(
        c,
        "getEnumConstants",
        "()[Ljava/lang/Object;",
        native_class_get_enum_constants,
    );
    // Three JDK enums whose constants the synthetic model did not carry.
    // `--synthetic-jdk` only, for the reason `native_enum_value_of` states: in
    // real-JDK mode the real `<clinit>` and `values()` bytecode run and a
    // registration here would only shadow them. `<clinit>` is additionally
    // runtime-gated inside `publish_synthetic_enum_constants` on
    // `is_class_synthetic_stub`, so a feature-enabled binary in real-JDK mode
    // leaves the JDK's own interned constants alone.
    //
    // The constant lists live beside the publisher in `lang_class`, and must
    // stay identical to `class_manager.rs`'s `enum_constant_fields` rows — that
    // side declares the statics, this side fills them, and declared-but-unfilled
    // is a NULL constant, which is worse than the `NoSuchFieldError` it
    // replaces.
    #[cfg(feature = "synthetic-jdk")]
    {
        registry.register(
            "java/time/DayOfWeek",
            "<clinit>",
            "()V",
            crate::lang_class::day_of_week_clinit,
        );
        registry.register(
            "java/time/DayOfWeek",
            "values",
            "()[Ljava/time/DayOfWeek;",
            crate::lang_class::day_of_week_values,
        );
        registry.register(
            "java/net/http/HttpClient$Version",
            "<clinit>",
            "()V",
            crate::lang_class::http_version_clinit,
        );
        registry.register(
            "java/net/http/HttpClient$Version",
            "values",
            "()[Ljava/net/http/HttpClient$Version;",
            crate::lang_class::http_version_values,
        );
        registry.register(
            "java/net/http/HttpClient$Redirect",
            "<clinit>",
            "()V",
            crate::lang_class::http_redirect_clinit,
        );
        registry.register(
            "java/net/http/HttpClient$Redirect",
            "values",
            "()[Ljava/net/http/HttpClient$Redirect;",
            crate::lang_class::http_redirect_values,
        );
    }

    // `Enum.valueOf(Class, String)` — synthetic-JDK only. See
    // `lang_class::native_enum_value_of`: `java/lang/Enum`'s natives were
    // retired against the real-JDK suite, where the real bytecode serves them,
    // and this mode has none. Registered here beside the constant source it
    // shares so the two stay together.
    #[cfg(feature = "synthetic-jdk")]
    registry.register(
        "java/lang/Enum",
        "valueOf",
        "(Ljava/lang/Class;Ljava/lang/String;)Ljava/lang/Enum;",
        crate::lang_class::native_enum_value_of,
    );
    // Package-private `Class.getEnumConstantsShared()` — backs
    // `EnumMap.getKeyUniverse` via `SharedSecrets.getJavaLangAccess()`.
    // The real JDK implements it in Java using reflection (getMethod +
    // invoke on `values()`), but our reflection stack still returns null
    // for synthetic enum `values()` methods, so `EnumMap.<init>(Class)`
    // sees a null array and throws NPE on `arraylength`.  Override with
    // the same native so EnumMap / StreamOpFlag.<clinit> succeed.
    registry.register(
        c,
        "getEnumConstantsShared",
        "()[Ljava/lang/Object;",
        native_class_get_enum_constants,
    );
    registry.register(c, "desiredAssertionStatus", "()Z", native_assertion_status);
    registry.register(
        c,
        "cast",
        "(Ljava/lang/Object;)Ljava/lang/Object;",
        native_class_cast,
    );
    registry.register(
        c,
        "asSubclass",
        "(Ljava/lang/Class;)Ljava/lang/Class;",
        native_class_as_subclass,
    );
    registry.register(
        c,
        "getClassLoader",
        "()Ljava/lang/ClassLoader;",
        lang_class::native_class_get_class_loader,
    );
    registry.register(
        c,
        "toGenericString",
        "()Ljava/lang/String;",
        native_class_get_type_name,
    );
    registry.register(
        c,
        "descriptorString",
        "()Ljava/lang/String;",
        native_class_descriptor_string,
    );

    // --- Formatter (basic) ---
    register_formatter_natives(registry);

    // Note: StringWriter and StringReader already registered in io.rs

    // --- Collections extras: unmodifiable wrappers ---
    register_collections_extras_natives(registry);
    register_core_stdlib_extras(registry);
    // `register_scanner_natives` used to be called here. Its twelve
    // `java/util/Scanner` registrations were overwritten by `native-io`'s two
    // lines later in the boot sequence, in every configuration; see the note
    // where it used to live in `phases_early.rs`.

    // Note: CompletableFuture, Executors, Locale, Charset already registered in earlier phases;
}

// ===========================================================================
// AtomicBoolean — 1-field synthetic (value=0 Int, 0 or 1)
// ===========================================================================

const AB_FIELD_VALUE: usize = 0;

// ===========================================================================
// AtomicStampedReference — JDK-faithful single `pair` field (slot 0) that
// holds an `AtomicStampedReference$Pair { reference@0, stamp@1 }`.
//
// The real class declares exactly ONE instance field (`private volatile
// Pair<V> pair`) plus a static `PAIR` VarHandle, so the allocated object has
// num_slots==1. The old intrinsic stored `stamp` directly at slot 1, which is
// out-of-bounds on a 1-slot object → the GC guard dropped the write and
// `getStamp` read garbage. Worse, every public ASR method (`getReference`,
// `getStamp`, `get`, `compareAndSet`, `set`, `attemptStamp`) reads
// `this.pair.reference` / `this.pair.stamp`, so any of these methods that the
// intrinsic does NOT intercept (e.g. `casPair`, or a future method) runs real
// bytecode against slot 0 expecting a Pair — finding a bare reference instead
// and reading bogus interior fields (the source of the stray `index=3`
// out-of-bounds writes during boot). Modelling the real Pair object keeps the
// intrinsic and any real bytecode perfectly consistent.
// ===========================================================================

const ASR_PAIR_CLASS: &str = "java/util/concurrent/atomic/AtomicStampedReference$Pair";

/// Allocate a real-layout `AtomicStampedReference$Pair` holding
/// `(reference, stamp)`. Slot 0 = reference (Object), slot 1 = stamp (int),
/// matching the JDK field order so real ASR bytecode reading `pair.reference`
/// / `pair.stamp` stays consistent with the intrinsic.
fn asr_alloc_pair(
    ctx: &mut dyn NativeContext,
    reference: Value,
    stamp: i32,
) -> Result<ObjectRef, MethodCallFailed> {
    // `alloc_concurrent_synthetic` resolves the real Pair class (2 fields) when
    // loadable and falls back to a 2-field synthetic class otherwise, so the
    // header's declared field count always matches the 2 slots we write.
    let pair = try_alloc_concurrent_synthetic(ctx, ASR_PAIR_CLASS, 2)?;
    ctx.set_field(pair, 0, reference);
    ctx.set_field(pair, 1, Value::Int(stamp));
    Ok(pair)
}

/// Read `(reference, stamp)` out of the `pair` stored in `this.field(0)`.
/// Returns `(Value::Object(None), 0)` if the pair slot is null or somehow not
/// a 2-field object (defensive — should not happen after construction).
fn asr_read_pair(ctx: &mut dyn NativeContext, this: ObjectRef) -> (Value, i32) {
    match ctx.get_field(this, 0) {
        Value::Object(Some(pair)) => {
            let reference = ctx.get_field(pair, 0);
            let stamp = match ctx.get_field(pair, 1) {
                Value::Int(v) => v,
                _ => 0,
            };
            (reference, stamp)
        }
        _ => (Value::Object(None), 0),
    }
}

// ===========================================================================
// AtomicMarkableReference — JDK-faithful single `pair` field (slot 0) that
// holds an `AtomicMarkableReference$Pair { reference@0, mark@1 }`.
//
// Same bug class as AtomicStampedReference above (see its comment): the real
// class declares exactly ONE instance field (`private volatile Pair<V>
// pair`) plus a static `PAIR` VarHandle, so the allocated object has
// num_slots==1. The old intrinsic stored `mark` directly at slot 1, which is
// out-of-bounds on a 1-slot object -> the GC guard silently dropped the
// write and every subsequent `isMarked`/`compareAndSet`/`attemptMark` read a
// stale mark forever. A caller spinning on `compareAndSet(ref, ref, false,
// true)` waiting for the mark to flip to `true` never observes it and
// busy-loops/never completes — this was the root cause of ES
// `RestClientSingleHostIntegTests` (`testManyAsyncRequests`) timing out:
// Apache httpasyncclient's reactor session-request tracking uses
// `AtomicMarkableReference`. Also: `get(boolean[])` was never registered as
// a native at all, so real bytecode ran unintercepted against slot 0
// expecting a `Pair` — finding the bare corrupted reference stored there by
// `native_amr_set`/`native_amr_init` instead and throwing
// `ClassCastException`. Modelling the real Pair object (as
// AtomicStampedReference already does) keeps the intrinsic and any real
// bytecode perfectly consistent.
// ===========================================================================

const AMR_PAIR_CLASS: &str = "java/util/concurrent/atomic/AtomicMarkableReference$Pair";

/// Allocate a real-layout `AtomicMarkableReference$Pair` holding
/// `(reference, mark)`. Slot 0 = reference (Object), slot 1 = mark (boolean,
/// stored as Int 0/1), matching the JDK field order so real AMR bytecode
/// reading `pair.reference` / `pair.mark` stays consistent with the
/// intrinsic.
fn amr_alloc_pair(
    ctx: &mut dyn NativeContext,
    reference: Value,
    mark: bool,
) -> Result<ObjectRef, MethodCallFailed> {
    // `alloc_concurrent_synthetic` resolves the real Pair class (2 fields) when
    // loadable and falls back to a 2-field synthetic class otherwise, so the
    // header's declared field count always matches the 2 slots we write.
    let pair = try_alloc_concurrent_synthetic(ctx, AMR_PAIR_CLASS, 2)?;
    ctx.set_field(pair, 0, reference);
    ctx.set_field(pair, 1, Value::Int(if mark { 1 } else { 0 }));
    Ok(pair)
}

/// Read `(reference, mark)` out of the `pair` stored in `this.field(0)`.
/// Returns `(Value::Object(None), false)` if the pair slot is null or somehow
/// not a 2-field object (defensive — should not happen after construction).
fn amr_read_pair(ctx: &mut dyn NativeContext, this: ObjectRef) -> (Value, bool) {
    match ctx.get_field(this, 0) {
        Value::Object(Some(pair)) => {
            let reference = ctx.get_field(pair, 0);
            let mark = match ctx.get_field(pair, 1) {
                Value::Int(v) => v != 0,
                _ => false,
            };
            (reference, mark)
        }
        _ => (Value::Object(None), false),
    }
}

fn native_amr_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let r = args.get(1).copied().unwrap_or(Value::Object(None));
    let mark = matches!(args.get(2), Some(Value::Int(v)) if *v != 0);
    let pair = amr_alloc_pair(ctx, r, mark);
    ctx.set_field(this, 0, Value::Object(Some(pair?)));
    Ok(None)
}

fn native_amr_get_ref(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let (reference, _mark) = amr_read_pair(ctx, this);
    Ok(Some(reference))
}

fn native_amr_is_marked(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let (_reference, mark) = amr_read_pair(ctx, this);
    Ok(Some(Value::Int(if mark { 1 } else { 0 })))
}

/// `V get(boolean[] markHolder)` — store the current mark into
/// `markHolder[0]` and return the current reference (matches JDK semantics).
fn native_amr_get_with_holder(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let (reference, mark) = amr_read_pair(ctx, this);
    if let Some(Value::Object(Some(holder))) = args.get(1) {
        ctx.set_array_element(*holder, 0, Value::Int(if mark { 1 } else { 0 }));
    }
    Ok(Some(reference))
}

fn native_amr_set(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let r = args.get(1).copied().unwrap_or(Value::Object(None));
    let mark = matches!(args.get(2), Some(Value::Int(v)) if *v != 0);
    // JDK `set` allocates a fresh Pair only when reference or mark differ; we
    // always install a fresh Pair (semantically identical, slightly simpler).
    let pair = amr_alloc_pair(ctx, r, mark);
    ctx.set_field(this, 0, Value::Object(Some(pair?)));
    Ok(None)
}

fn native_amr_attempt_mark(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let expected_ref = args.get(1).copied().unwrap_or(Value::Object(None));
    let new_mark = matches!(args.get(2), Some(Value::Int(v)) if *v != 0);
    let (current_ref, _current_mark) = amr_read_pair(ctx, this);
    if values_ref_equal(current_ref, expected_ref) {
        // Swap in a new Pair carrying the (unchanged) reference + new mark.
        let pair = amr_alloc_pair(ctx, current_ref, new_mark);
        ctx.set_field(this, 0, Value::Object(Some(pair?)));
        Ok(Some(Value::Int(1)))
    } else {
        Ok(Some(Value::Int(0)))
    }
}

fn native_amr_cas(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let expected_ref = args.get(1).copied().unwrap_or(Value::Object(None));
    let new_ref = args.get(2).copied().unwrap_or(Value::Object(None));
    let expected_mark = matches!(args.get(3), Some(Value::Int(v)) if *v != 0);
    let new_mark = matches!(args.get(4), Some(Value::Int(v)) if *v != 0);
    let (current_ref, current_mark) = amr_read_pair(ctx, this);
    if values_ref_equal(current_ref, expected_ref) && current_mark == expected_mark {
        // Install a new Pair only if reference or mark actually changes (the
        // JDK fast-path: when both are identical it skips the casPair entirely).
        if !values_ref_equal(current_ref, new_ref) || current_mark != new_mark {
            let pair = amr_alloc_pair(ctx, new_ref, new_mark);
            ctx.set_field(this, 0, Value::Object(Some(pair?)));
        }
        Ok(Some(Value::Int(1)))
    } else {
        Ok(Some(Value::Int(0)))
    }
}

/// Reference equality helper for atomic CAS operations
fn values_ref_equal(a: Value, b: Value) -> bool {
    match (a, b) {
        (Value::Object(None), Value::Object(None)) => true,
        (Value::Object(Some(ra)), Value::Object(Some(rb))) => ra == rb,
        (Value::Int(a), Value::Int(b)) => a == b,
        (Value::Long(a), Value::Long(b)) => a == b,
        _ => false,
    }
}

