// -----------------------------------------------------------------------------
// Stream Gatherers (JEP 473)
// -----------------------------------------------------------------------------

/// Gatherer layout: 5-field synthetic.
/// `[0]=initializer, [1]=integrator, [2]=combiner, [3]=finisher, [4]=kind`
/// kind: 0=custom, 1=windowFixed, 2=windowSliding, 3=fold, 4=scan, 5=mapConcurrent
const GATHERER_KIND_CUSTOM: i32 = 0;
const GATHERER_KIND_WINDOW_FIXED: i32 = 1;
const GATHERER_KIND_WINDOW_SLIDING: i32 = 2;
const GATHERER_KIND_FOLD: i32 = 3;
const GATHERER_KIND_SCAN: i32 = 4;
const GATHERER_KIND_MAP_CONCURRENT: i32 = 5;

fn register_pd_stream_gatherers(r: &mut NativeMethodRegistry) {
    let stream = "java/util/stream/Stream";

    r.register(
        stream,
        "gather",
        "(Ljava/util/stream/Gatherer;)Ljava/util/stream/Stream;",
        pd_stream_gather,
    );

    let gatherer = "java/util/stream/Gatherer";
    r.register(
        gatherer,
        "initializer",
        "()Ljava/util/function/Supplier;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 0)))
        },
    );
    r.register(
        gatherer,
        "integrator",
        "()Ljava/util/stream/Gatherer$Integrator;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 1)))
        },
    );
    r.register(
        gatherer,
        "combiner",
        "()Ljava/util/function/BinaryOperator;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 2)))
        },
    );
    r.register(
        gatherer,
        "finisher",
        "()Ljava/util/function/BiConsumer;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 3)))
        },
    );

    r.register(gatherer, "ofSequential", "(Ljava/util/function/Supplier;Ljava/util/stream/Gatherer$Integrator;Ljava/util/function/BiConsumer;)Ljava/util/stream/Gatherer;", |ctx, args| {
        let initializer = args.first().copied().unwrap_or(Value::Object(None));
        let integrator = args.get(1).copied().unwrap_or(Value::Object(None));
        let finisher = args.get(2).copied().unwrap_or(Value::Object(None));
        let g = try_alloc_concurrent_synthetic(ctx, "java/util/stream/Gatherer", 5)?;
        ctx.set_field(g, 0, initializer);
        ctx.set_field(g, 1, integrator);
        ctx.set_field(g, 2, Value::Object(None));
        ctx.set_field(g, 3, finisher);
        ctx.set_field(g, 4, Value::Int(GATHERER_KIND_CUSTOM));
        Ok(Some(Value::Object(Some(g))))
    });

    // The TWO-argument `ofSequential(Supplier, Integrator)` — added because its
    // absence here was an out-of-bounds read, not a missing feature.
    //
    // `java/util/stream/Gatherer` has NO `synthetic_stub_fields` arm, so
    // `class_num_total_fields` answers 0 and `try_alloc_concurrent_synthetic`'s
    // `num_fields.max(real)` leaves the caller's request as the LITERAL object
    // width. Two registrars model this class at two widths with two different
    // slot maps:
    //
    //   this file            5 slots: initializer 0, integrator 1, combiner 2,
    //                        finisher 3, KIND 4
    //   phases_late/streams.rs  3 slots: initializer 0, integrator 1, finisher 2
    //
    // `register_phase_d_natives` (this one) runs AFTER `register_phase67_natives`
    // inside `register_synthetic_overrides`, and `register()` is
    // last-registration-wins, so this file's accessors and `Stream.gather` win
    // for every triple both files spell. Every 3-slot factory in `streams.rs`
    // was therefore shadowed by a 5-slot one here — EXCEPT this overload, which
    // only `streams.rs` registered (`streams.rs:4541`). Its 3-slot product then
    // reached `pd_stream_gather`, whose first act is `ctx.get_field(gatherer, 4)`:
    // `Heap::get_field` asserts `index < num_slots`, so `stream.gather(g)` on a
    // gatherer from this overload aborts the VM with "field index 4 out of
    // bounds (num_slots=3)". `finisher()` (slot 3) is the same panic one slot
    // lower, and `combiner()` (slot 2) would have returned the FINISHER.
    //
    // Registering it here shadows the 3-slot factory with the same 5-slot shape
    // the sibling overloads already use, which is the whole fix; the alternative
    // (widening `streams.rs` to 5) would leave two copies of one slot map.
    // Verified against the oracle: `javap -p java.util.stream.Gatherer` on
    // JDK 25.0.3 declares all four of `ofSequential`'s/`of`'s arities, of which
    // this VM serves three — see
    // docs/known-issues/jdk-only/E35-R11-SYNTHETIC-WIDTH-SWEEP-20260813.md §3.1.
    r.register(gatherer, "ofSequential", "(Ljava/util/function/Supplier;Ljava/util/stream/Gatherer$Integrator;)Ljava/util/stream/Gatherer;", |ctx, args| {
        let initializer = args.first().copied().unwrap_or(Value::Object(None));
        let integrator = args.get(1).copied().unwrap_or(Value::Object(None));
        let g = try_alloc_concurrent_synthetic(ctx, "java/util/stream/Gatherer", 5)?;
        ctx.set_field(g, 0, initializer);
        ctx.set_field(g, 1, integrator);
        ctx.set_field(g, 2, Value::Object(None));
        ctx.set_field(g, 3, Value::Object(None));
        ctx.set_field(g, 4, Value::Int(GATHERER_KIND_CUSTOM));
        Ok(Some(Value::Object(Some(g))))
    });

    r.register(
        gatherer,
        "of",
        "(Ljava/util/stream/Gatherer$Integrator;)Ljava/util/stream/Gatherer;",
        |ctx, args| {
            let integrator = args.first().copied().unwrap_or(Value::Object(None));
            let g = try_alloc_concurrent_synthetic(ctx, "java/util/stream/Gatherer", 5)?;
            ctx.set_field(g, 0, Value::Object(None));
            ctx.set_field(g, 1, integrator);
            ctx.set_field(g, 2, Value::Object(None));
            ctx.set_field(g, 3, Value::Object(None));
            ctx.set_field(g, 4, Value::Int(GATHERER_KIND_CUSTOM));
            Ok(Some(Value::Object(Some(g))))
        },
    );

    // NOTE: `Gatherer$Integrator.integrate(...)Z` is deliberately NOT
    // registered. It used to answer a constant `true` ("keep going") while
    // pushing nothing downstream — i.e. it consumed the element and dropped
    // it, so any gather() whose integrator reached this native produced an
    // EMPTY result instead of the user's. `integrate` is the SAM of an
    // interface: a lambda implementation is served by `try_lambda_dispatch`
    // before any native lookup, and a class implementation declares its own
    // `integrate`, so the real body is what the gather loop below
    // (`ctx.invoke_virtual(integrator, "integrate", ...)`) needs to reach.
    // Nothing in the tree allocates a synthetic receiver whose class IS
    // `Gatherer$Integrator`, so there is no caller left for a native here.
    let downstream = "java/util/stream/Gatherer$Downstream";
    r.register(downstream, "push", "(Ljava/lang/Object;)Z", |ctx, args| {
        // Downstream is a 2-field synthetic: [0]=backing array, [1]=size
        let this = obj_arg(args, 0)?;
        let value = args.get(1).copied().unwrap_or(Value::Object(None));
        if let Value::Object(Some(arr)) = ctx.get_field(this, 0) {
            let size = match ctx.get_field(this, 1) {
                Value::Int(n) => n as usize,
                _ => 0,
            };
            let arr_len = ctx.array_length(arr);
            if size < arr_len {
                ctx.set_array_element(arr, size, value);
                ctx.set_field(this, 1, Value::Int((size + 1) as i32));
            }
        }
        Ok(Some(Value::Int(1)))
    });

    let gatherers = "java/util/stream/Gatherers";

    r.register(
        gatherers,
        "fold",
        "(Ljava/util/function/Supplier;Ljava/util/function/BiFunction;)Ljava/util/stream/Gatherer;",
        |ctx, args| {
            let initial = args.first().copied().unwrap_or(Value::Object(None));
            let folder = args.get(1).copied().unwrap_or(Value::Object(None));
            let g = try_alloc_concurrent_synthetic(ctx, "java/util/stream/Gatherer", 5)?;
            ctx.set_field(g, 0, initial);
            ctx.set_field(g, 1, folder);
            ctx.set_field(g, 2, Value::Object(None));
            ctx.set_field(g, 3, Value::Object(None));
            ctx.set_field(g, 4, Value::Int(GATHERER_KIND_FOLD));
            Ok(Some(Value::Object(Some(g))))
        },
    );

    r.register(
        gatherers,
        "scan",
        "(Ljava/util/function/Supplier;Ljava/util/function/BiFunction;)Ljava/util/stream/Gatherer;",
        |ctx, args| {
            let initial = args.first().copied().unwrap_or(Value::Object(None));
            let scanner = args.get(1).copied().unwrap_or(Value::Object(None));
            let g = try_alloc_concurrent_synthetic(ctx, "java/util/stream/Gatherer", 5)?;
            ctx.set_field(g, 0, initial);
            ctx.set_field(g, 1, scanner);
            ctx.set_field(g, 2, Value::Object(None));
            ctx.set_field(g, 3, Value::Object(None));
            ctx.set_field(g, 4, Value::Int(GATHERER_KIND_SCAN));
            Ok(Some(Value::Object(Some(g))))
        },
    );

    r.register(
        gatherers,
        "windowFixed",
        "(I)Ljava/util/stream/Gatherer;",
        |ctx, args| {
            let window_size = match args.first() {
                Some(Value::Int(n)) => *n,
                _ => 1,
            };
            let g = try_alloc_concurrent_synthetic(ctx, "java/util/stream/Gatherer", 5)?;
            ctx.set_field(g, 0, Value::Int(window_size));
            ctx.set_field(g, 1, Value::Object(None));
            ctx.set_field(g, 2, Value::Object(None));
            ctx.set_field(g, 3, Value::Object(None));
            ctx.set_field(g, 4, Value::Int(GATHERER_KIND_WINDOW_FIXED));
            Ok(Some(Value::Object(Some(g))))
        },
    );

    r.register(
        gatherers,
        "windowSliding",
        "(I)Ljava/util/stream/Gatherer;",
        |ctx, args| {
            let window_size = match args.first() {
                Some(Value::Int(n)) => *n,
                _ => 1,
            };
            let g = try_alloc_concurrent_synthetic(ctx, "java/util/stream/Gatherer", 5)?;
            ctx.set_field(g, 0, Value::Int(window_size));
            ctx.set_field(g, 1, Value::Object(None));
            ctx.set_field(g, 2, Value::Object(None));
            ctx.set_field(g, 3, Value::Object(None));
            ctx.set_field(g, 4, Value::Int(GATHERER_KIND_WINDOW_SLIDING));
            Ok(Some(Value::Object(Some(g))))
        },
    );

    r.register(
        gatherers,
        "mapConcurrent",
        "(ILjava/util/function/Function;)Ljava/util/stream/Gatherer;",
        |ctx, args| {
            let function = args.get(1).copied().unwrap_or(Value::Object(None));
            let g = try_alloc_concurrent_synthetic(ctx, "java/util/stream/Gatherer", 5)?;
            ctx.set_field(g, 0, Value::Object(None));
            ctx.set_field(g, 1, function);
            ctx.set_field(g, 2, Value::Object(None));
            ctx.set_field(g, 3, Value::Object(None));
            ctx.set_field(g, 4, Value::Int(GATHERER_KIND_MAP_CONCURRENT));
            Ok(Some(Value::Object(Some(g))))
        },
    );
}

/// Stream.gather(Gatherer) — dispatches by gatherer kind for correct semantics.
fn pd_stream_gather(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let gatherer = obj_arg(args, 1)?;
    let elems = p56_read_stream_elems(ctx, this);

    let kind = match ctx.get_field(gatherer, 4) {
        Value::Int(k) => k,
        _ => GATHERER_KIND_CUSTOM,
    };

    let result = match kind {
        GATHERER_KIND_FOLD => pd_gather_fold(ctx, &elems, gatherer)?,
        GATHERER_KIND_SCAN => pd_gather_scan(ctx, &elems, gatherer)?,
        GATHERER_KIND_WINDOW_FIXED => pd_gather_window_fixed(ctx, &elems, gatherer)?,
        GATHERER_KIND_WINDOW_SLIDING => pd_gather_window_sliding(ctx, &elems, gatherer)?,
        GATHERER_KIND_MAP_CONCURRENT => pd_gather_map(ctx, &elems, gatherer)?,
        _ => pd_gather_custom(ctx, &elems, gatherer)?,
    };

    let stream = p56_build_stream(ctx, result, "java/util/stream/Stream");
    Ok(Some(Value::Object(Some(stream?))))
}

fn pd_gather_fold(
    ctx: &mut dyn NativeContext,
    elems: &[Value],
    gatherer: ObjectRef,
) -> Result<Vec<Value>, MethodCallFailed> {
    let mut state = if let Value::Object(Some(init)) = ctx.get_field(gatherer, 0) {
        ctx.invoke_virtual(init, "get", "()Ljava/lang/Object;", &[])?
            .unwrap_or(Value::Object(None))
    } else {
        Value::Object(None)
    };
    if let Value::Object(Some(folder)) = ctx.get_field(gatherer, 1) {
        for elem in elems {
            state = ctx
                .invoke_virtual(
                    folder,
                    "apply",
                    "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",
                    &[state, *elem],
                )?
                .unwrap_or(Value::Object(None));
        }
    }
    Ok(vec![state])
}

fn pd_gather_scan(
    ctx: &mut dyn NativeContext,
    elems: &[Value],
    gatherer: ObjectRef,
) -> Result<Vec<Value>, MethodCallFailed> {
    let mut state = if let Value::Object(Some(init)) = ctx.get_field(gatherer, 0) {
        ctx.invoke_virtual(init, "get", "()Ljava/lang/Object;", &[])?
            .unwrap_or(Value::Object(None))
    } else {
        Value::Object(None)
    };
    let mut result = Vec::with_capacity(elems.len());
    if let Value::Object(Some(scanner)) = ctx.get_field(gatherer, 1) {
        for elem in elems {
            state = ctx
                .invoke_virtual(
                    scanner,
                    "apply",
                    "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",
                    &[state, *elem],
                )?
                .unwrap_or(Value::Object(None));
            result.push(state);
        }
    }
    Ok(result)
}

fn pd_gather_window_fixed(
    _ctx: &mut dyn NativeContext,
    elems: &[Value],
    gatherer: ObjectRef,
) -> Result<Vec<Value>, MethodCallFailed> {
    let window_size = match _ctx.get_field(gatherer, 0) {
        Value::Int(n) => n.max(1) as usize,
        _ => 1,
    };
    // Each window becomes an ArrayList in the output stream
    let mut result = Vec::new();
    for chunk in elems.chunks(window_size) {
        let al = try_alloc_concurrent_synthetic(_ctx, "java/util/ArrayList", 2)?;
        let arr = _ctx.new_array(cratonvm_types::ArrayElementType::Reference, chunk.len());
        for (i, v) in chunk.iter().enumerate() {
            _ctx.set_array_element(arr, i, *v);
        }
        _ctx.set_field(al, 0, Value::Object(Some(arr)));
        _ctx.set_field(al, 1, Value::Int(chunk.len() as i32));
        result.push(Value::Object(Some(al)));
    }
    Ok(result)
}

fn pd_gather_window_sliding(
    _ctx: &mut dyn NativeContext,
    elems: &[Value],
    gatherer: ObjectRef,
) -> Result<Vec<Value>, MethodCallFailed> {
    let window_size = match _ctx.get_field(gatherer, 0) {
        Value::Int(n) => n.max(1) as usize,
        _ => 1,
    };
    let mut result = Vec::new();
    if elems.len() >= window_size {
        for start in 0..=(elems.len() - window_size) {
            let window = &elems[start..start + window_size];
            let al = try_alloc_concurrent_synthetic(_ctx, "java/util/ArrayList", 2)?;
            let arr = _ctx.new_array(cratonvm_types::ArrayElementType::Reference, window.len());
            for (i, v) in window.iter().enumerate() {
                _ctx.set_array_element(arr, i, *v);
            }
            _ctx.set_field(al, 0, Value::Object(Some(arr)));
            _ctx.set_field(al, 1, Value::Int(window.len() as i32));
            result.push(Value::Object(Some(al)));
        }
    }
    Ok(result)
}

fn pd_gather_map(
    ctx: &mut dyn NativeContext,
    elems: &[Value],
    gatherer: ObjectRef,
) -> Result<Vec<Value>, MethodCallFailed> {
    let mut result = Vec::with_capacity(elems.len());
    if let Value::Object(Some(func)) = ctx.get_field(gatherer, 1) {
        for elem in elems {
            let mapped = ctx
                .invoke_virtual(
                    func,
                    "apply",
                    "(Ljava/lang/Object;)Ljava/lang/Object;",
                    &[*elem],
                )?
                .unwrap_or(Value::Object(None));
            result.push(mapped);
        }
    }
    Ok(result)
}

fn pd_gather_custom(
    ctx: &mut dyn NativeContext,
    elems: &[Value],
    gatherer: ObjectRef,
) -> Result<Vec<Value>, MethodCallFailed> {
    let initializer = ctx.get_field(gatherer, 0);
    let integrator_val = ctx.get_field(gatherer, 1);
    let finisher = ctx.get_field(gatherer, 3);

    let state = if let Value::Object(Some(init_ref)) = initializer {
        ctx.invoke_virtual(init_ref, "get", "()Ljava/lang/Object;", &[])?
            .unwrap_or(Value::Object(None))
    } else {
        Value::Object(None)
    };

    // Create a downstream collector: [0]=backing array, [1]=size
    let downstream =
        try_alloc_concurrent_synthetic(ctx, "java/util/stream/Gatherer$Downstream", 2)?;
    let downstream_arr = ctx.new_array(
        cratonvm_types::ArrayElementType::Reference,
        elems.len() + 16,
    );
    ctx.set_field(downstream, 0, Value::Object(Some(downstream_arr)));
    ctx.set_field(downstream, 1, Value::Int(0));

    if let Value::Object(Some(integrator)) = integrator_val {
        for elem in elems {
            let cont = ctx.invoke_virtual(
                integrator,
                "integrate",
                "(Ljava/lang/Object;Ljava/lang/Object;Ljava/util/stream/Gatherer$Downstream;)Z",
                &[state, *elem, Value::Object(Some(downstream))],
            );
            if let Ok(Some(Value::Int(0))) = cont {
                break;
            }
        }
    }

    if let Value::Object(Some(finisher_ref)) = finisher {
        let _ = ctx.invoke_virtual(
            finisher_ref,
            "accept",
            "(Ljava/lang/Object;Ljava/lang/Object;)V",
            &[state, Value::Object(Some(downstream))],
        );
    }

    // Read collected downstream values
    let ds_size = match ctx.get_field(downstream, 1) {
        Value::Int(n) => n as usize,
        _ => 0,
    };
    let ds_arr = ctx.get_field(downstream, 0);
    let mut result = Vec::with_capacity(ds_size);
    if let Value::Object(Some(arr)) = ds_arr {
        for i in 0..ds_size {
            result.push(ctx.get_array_element(arr, i));
        }
    }

    if result.is_empty() && !elems.is_empty() && integrator_val == Value::Object(None) {
        result = elems.to_vec();
    }

    Ok(result)
}

// -----------------------------------------------------------------------------
// Scoped Values (JEP 446, finalized in Java 25)
// -----------------------------------------------------------------------------

fn register_pd_scoped_values(r: &mut NativeMethodRegistry) {
    let sv = "java/lang/ScopedValue";

    r.register(
        sv,
        "newInstance",
        "()Ljava/lang/ScopedValue;",
        |ctx, _args| {
            let obj = try_alloc_concurrent_synthetic(ctx, "java/lang/ScopedValue", 2)?;
            Ok(Some(Value::Object(Some(obj))))
        },
    );

    r.register(sv, "get", "()Ljava/lang/Object;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let key_id = ctx.identity_hash_code(this) as u64;
        match ctx.get_scoped_value(key_id) {
            Some(val) => Ok(Some(val)),
            None => Err(RuntimeError::IllegalStateException {
                message: "ScopedValue is not bound".to_string(),
            }
            .into()),
        }
    });

    r.register(sv, "isBound", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let key_id = ctx.identity_hash_code(this) as u64;
        Ok(Some(Value::Int(
            if ctx.get_scoped_value(key_id).is_some() {
                1
            } else {
                0
            },
        )))
    });

    r.register(
        sv,
        "orElse",
        "(Ljava/lang/Object;)Ljava/lang/Object;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let other = args.get(1).copied().unwrap_or(Value::Object(None));
            let key_id = ctx.identity_hash_code(this) as u64;
            Ok(Some(ctx.get_scoped_value(key_id).unwrap_or(other)))
        },
    );

    r.register(
        sv,
        "orElseThrow",
        "(Ljava/util/function/Supplier;)Ljava/lang/Object;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let key_id = ctx.identity_hash_code(this) as u64;
            match ctx.get_scoped_value(key_id) {
                Some(val) => Ok(Some(val)),
                None => Err(RuntimeError::IllegalStateException {
                    message: "ScopedValue is not bound".to_string(),
                }
                .into()),
            }
        },
    );

    r.register(
        sv,
        "where",
        "(Ljava/lang/ScopedValue;Ljava/lang/Object;)Ljava/lang/ScopedValue$Carrier;",
        |ctx, args| {
            let scoped_val = args.first().copied().unwrap_or(Value::Object(None));
            let value = args.get(1).copied().unwrap_or(Value::Object(None));
            let carrier = try_alloc_concurrent_synthetic(ctx, "java/lang/ScopedValue$Carrier", 3)?;
            ctx.set_field(carrier, 0, scoped_val);
            ctx.set_field(carrier, 1, value);
            ctx.set_field(carrier, 2, Value::Object(None));
            Ok(Some(Value::Object(Some(carrier))))
        },
    );

    let carrier = "java/lang/ScopedValue$Carrier";

    r.register(
        carrier,
        "where",
        "(Ljava/lang/ScopedValue;Ljava/lang/Object;)Ljava/lang/ScopedValue$Carrier;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let scoped_val = args.get(1).copied().unwrap_or(Value::Object(None));
            let value = args.get(2).copied().unwrap_or(Value::Object(None));
            let new_carrier =
                try_alloc_concurrent_synthetic(ctx, "java/lang/ScopedValue$Carrier", 3)?;
            ctx.set_field(new_carrier, 0, scoped_val);
            ctx.set_field(new_carrier, 1, value);
            ctx.set_field(new_carrier, 2, Value::Object(Some(this)));
            Ok(Some(Value::Object(Some(new_carrier))))
        },
    );

    // Carrier.run(Runnable) — push bindings, run, pop (exception-safe)
    r.register(carrier, "run", "(Ljava/lang/Runnable;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let runnable = obj_arg(args, 1)?;
        let bindings = pd_collect_carrier_bindings(ctx, this);
        let binding_count = bindings.len();
        for (key_id, key_ref, value) in &bindings {
            // Round-9 GC fix: pass the ScopedValue key ObjectRef so the
            // GC root scanner pins it for the binding's lifetime.
            ctx.push_scoped_value_with_key(*key_id, *key_ref, *value);
        }
        let result = ctx.invoke_virtual(runnable, "run", "()V", &[]);
        // Always pop bindings, even on error (exception safety)
        for _ in 0..binding_count {
            ctx.pop_scoped_value();
        }
        result?;
        Ok(None)
    });

    // Carrier.call(Callable) → T — push bindings, call, pop (exception-safe)
    r.register(
        carrier,
        "call",
        "(Ljava/util/concurrent/Callable;)Ljava/lang/Object;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let callable = obj_arg(args, 1)?;
            let bindings = pd_collect_carrier_bindings(ctx, this);
            let binding_count = bindings.len();
            for (key_id, key_ref, value) in &bindings {
                ctx.push_scoped_value_with_key(*key_id, *key_ref, *value);
            }
            let result = ctx.invoke_virtual(callable, "call", "()Ljava/lang/Object;", &[]);
            for _ in 0..binding_count {
                ctx.pop_scoped_value();
            }
            Ok(result?.or(Some(Value::Object(None))))
        },
    );

    r.register(
        carrier,
        "get",
        "(Ljava/lang/ScopedValue;)Ljava/lang/Object;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let scoped_val = obj_arg(args, 1)?;
            let target_key = ctx.identity_hash_code(scoped_val) as u64;
            let bindings = pd_collect_carrier_bindings(ctx, this);
            for (key_id, _key_ref, value) in bindings {
                if key_id == target_key {
                    return Ok(Some(value));
                }
            }
            Err(RuntimeError::IllegalStateException {
                message: "ScopedValue not in carrier".to_string(),
            }
            .into())
        },
    );
}

fn pd_collect_carrier_bindings(
    ctx: &mut dyn NativeContext,
    carrier: ObjectRef,
) -> Vec<(u64, Option<ObjectRef>, Value)> {
    // Round-9 GC fix: also carry the ScopedValue key ObjectRef so the
    // GC root scanner can pin it for the lifetime of the binding (was
    // missing — the JEP 446 key could be reclaimed while bound).
    let mut bindings = Vec::new();
    let mut current = Some(carrier);
    while let Some(c) = current {
        if let Value::Object(Some(sv_ref)) = ctx.get_field(c, 0) {
            let key_id = ctx.identity_hash_code(sv_ref) as u64;
            let value = ctx.get_field(c, 1);
            bindings.push((key_id, Some(sv_ref), value));
        }
        current = match ctx.get_field(c, 2) {
            Value::Object(Some(prev)) => Some(prev),
            _ => None,
        };
    }
    bindings
}

// -----------------------------------------------------------------------------
// Structured Concurrency (JEP 462, finalized in Java 25)
// -----------------------------------------------------------------------------

/// Shared helper: initialize a StructuredTaskScope (or subclass) with subtask list.
fn pd_init_scope(ctx: &mut dyn NativeContext, this: ObjectRef) -> Result<(), MethodCallFailed> {
    let subtasks = try_alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2)?;
    let arr = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 64);
    ctx.set_field(subtasks, 0, Value::Object(Some(arr)));
    ctx.set_field(subtasks, 1, Value::Int(0));
    ctx.set_field(this, 0, Value::Object(Some(subtasks)));
    ctx.set_field(this, 1, Value::Int(0)); // OPEN
    ctx.set_field(this, 2, Value::Long(ctx.thread_id() as i64));
    Ok(())
}

/// Shared helper: fork a callable synchronously into a scope's subtask list.
fn pd_fork_callable(
    ctx: &mut dyn NativeContext,
    scope: ObjectRef,
    callable: Value,
) -> MethodCallResult {
    let subtask =
        try_alloc_concurrent_synthetic(ctx, "java/util/concurrent/StructuredTaskScope$Subtask", 5)?;
    ctx.set_field(subtask, 0, callable);
    ctx.set_field(subtask, 3, Value::Int(0)); // UNAVAILABLE

    if let Value::Object(Some(callable_ref)) = callable {
        match ctx.invoke_virtual(callable_ref, "call", "()Ljava/lang/Object;", &[]) {
            Ok(result) => {
                ctx.set_field(subtask, 1, result.unwrap_or(Value::Object(None)));
                ctx.set_field(subtask, 3, Value::Int(1)); // SUCCESS
            }
            Err(e) => {
                // Store error description for Subtask.exception()
                let msg = ctx.create_string(&format!("{e}"));
                ctx.set_field(subtask, 2, Value::Object(Some(msg)));
                ctx.set_field(subtask, 3, Value::Int(2)); // FAILED
            }
        }
    }

    // Add subtask to scope's list (grow-safe: array is 64 slots)
    if let Value::Object(Some(subtasks)) = ctx.get_field(scope, 0) {
        if let Value::Object(Some(arr)) = ctx.get_field(subtasks, 0) {
            let size = match ctx.get_field(subtasks, 1) {
                Value::Int(n) => n as usize,
                _ => 0,
            };
            let arr_len = ctx.array_length(arr);
            if size < arr_len {
                ctx.set_array_element(arr, size, Value::Object(Some(subtask)));
                ctx.set_field(subtasks, 1, Value::Int((size + 1) as i32));
            }
        }
    }

    Ok(Some(Value::Object(Some(subtask))))
}

/// Shared helper: find first successful subtask result.
fn pd_first_success(ctx: &dyn NativeContext, scope: ObjectRef) -> Option<Value> {
    if let Value::Object(Some(subtasks)) = ctx.get_field(scope, 0) {
        let size = match ctx.get_field(subtasks, 1) {
            Value::Int(n) => n as usize,
            _ => 0,
        };
        if let Value::Object(Some(arr)) = ctx.get_field(subtasks, 0) {
            for i in 0..size {
                if let Value::Object(Some(st)) = ctx.get_array_element(arr, i) {
                    if matches!(ctx.get_field(st, 3), Value::Int(1)) {
                        return Some(ctx.get_field(st, 1));
                    }
                }
            }
        }
    }
    None
}

/// Check if any subtask failed.
fn pd_has_failure(ctx: &dyn NativeContext, scope: ObjectRef) -> bool {
    if let Value::Object(Some(subtasks)) = ctx.get_field(scope, 0) {
        let size = match ctx.get_field(subtasks, 1) {
            Value::Int(n) => n as usize,
            _ => 0,
        };
        if let Value::Object(Some(arr)) = ctx.get_field(subtasks, 0) {
            for i in 0..size {
                if let Value::Object(Some(st)) = ctx.get_array_element(arr, i) {
                    if matches!(ctx.get_field(st, 3), Value::Int(2)) {
                        return true;
                    }
                }
            }
        }
    }
    false
}

#[cfg(test)]
mod vector_support_essential_tests {
    use super::*;
    use crate::test_utils::MockNativeContext;
    #[allow(unused_imports)]
    use cratonvm_native_api::{
        NativeClassAccess, NativeExceptionAccess, NativeGpuAccess, NativeHeapAccess,
        NativeInvokeAccess, NativeSystemAccess, NativeThreadAccess,
    };

    #[test]
    fn register_essential_includes_jdk25_vector_support_natives() {
        let mut registry = NativeMethodRegistry::new();
        register_essential_natives(&mut registry);
        let vector_support = "jdk/internal/vm/vector/VectorSupport";

        assert!(registry
            .find(vector_support, "registerNatives", "()I")
            .is_some());
        assert!(registry
            .find(vector_support, "getCPUFeatures", "()Ljava/lang/String;")
            .is_some());
        assert!(registry
            .find(vector_support, "getMaxLaneCount", "(Ljava/lang/Class;)I")
            .is_some());
    }

    #[test]
    fn class_component_type_alias_is_registered() {
        for name in ["getComponentType", "componentType"] {
            let mut registry = NativeMethodRegistry::new();
            register_essential_natives(&mut registry);
            assert!(
                registry
                    .find("java/lang/Class", name, "()Ljava/lang/Class;")
                    .is_some(),
                "Class.{name}() must use the native array-component mirror path"
            );

            let mut final_registry = NativeMethodRegistry::new();
            register_enterprise_final_natives(&mut final_registry);
            assert!(
                final_registry
                    .find("java/lang/Class", name, "()Ljava/lang/Class;")
                    .is_some(),
                "Class.{name}() must also be registered in the final native set"
            );
        }
    }

    #[test]
    fn linked_blocking_queue_clear_preserves_real_jdk_count_field() {
        let mut registry = NativeMethodRegistry::new();
        register_essential_natives(&mut registry);
        let clear = registry
            .find("java/util/concurrent/LinkedBlockingQueue", "clear", "()V")
            .expect("essential LinkedBlockingQueue.clear native");

        let mut ctx = MockNativeContext::new();
        let queue_class = ctx
            .ensure_class_initialized("java/util/concurrent/LinkedBlockingQueue")
            .expect("mock queue class");
        let queue = ctx.alloc_object(queue_class, 3);
        let count_class = ctx
            .ensure_class_initialized("java/util/concurrent/atomic/AtomicInteger")
            .expect("mock AtomicInteger class");
        let count = ctx.alloc_object(count_class, 1);
        ctx.set_field(queue, 1, Value::Object(Some(count)));

        clear(&mut ctx, &[Value::Object(Some(queue))]).expect("clear succeeds");

        assert_eq!(
            ctx.get_field(queue, 1),
            Value::Object(Some(count)),
            "real-JDK LinkedBlockingQueue.count must not be stomped as synthetic size"
        );
        assert_eq!(
            ctx.get_field_by_name(queue, "count"),
            Value::Object(Some(count))
        );
    }
}

#[cfg(test)]
mod base64_encoder_tests {
    use super::*;
    use crate::test_utils::MockNativeContext;
    #[allow(unused_imports)]
    use cratonvm_native_api::{
        NativeClassAccess, NativeExceptionAccess, NativeGpuAccess, NativeHeapAccess,
        NativeInvokeAccess, NativeSystemAccess, NativeThreadAccess,
    };
    use cratonvm_types::ArrayElementType;

    #[test]
    fn url_encoder_without_padding_preserves_flag_for_encode_to_string() {
        let mut ctx = MockNativeContext::new();
        let encoder = match native_b64_get_url_encoder(&mut ctx, &[])
            .expect("getUrlEncoder succeeds")
            .expect("getUrlEncoder returns encoder")
        {
            Value::Object(Some(value)) => value,
            other => panic!("expected encoder, got {other:?}"),
        };
        let unpadded = match native_b64_without_padding(&mut ctx, &[Value::Object(Some(encoder))])
            .expect("withoutPadding succeeds")
            .expect("withoutPadding returns encoder")
        {
            Value::Object(Some(value)) => value,
            other => panic!("expected encoder, got {other:?}"),
        };
        let input = ctx.new_array(ArrayElementType::Byte, 2);
        ctx.set_array_element(input, 0, Value::Int(0xff));
        ctx.set_array_element(input, 1, Value::Int(0xff));

        let encoded = match native_b64_encode_to_string(
            &mut ctx,
            &[Value::Object(Some(unpadded)), Value::Object(Some(input))],
        )
        .expect("encodeToString succeeds")
        .expect("encodeToString returns a string")
        {
            Value::Object(Some(value)) => value,
            other => panic!("expected String, got {other:?}"),
        };

        assert_eq!(ctx.read_string(encoded).as_deref(), Some("__8"));
    }

    /// A null ARGUMENT to any `Base64` encode/decode overload is a
    /// `NullPointerException` on HotSpot 25 — measured for all 13
    /// encoder/decoder combinations, e.g.
    ///
    /// ```text
    /// Decoder.decode((String)null) -> java.lang.NullPointerException
    ///     / Cannot invoke "String.getBytes(java.nio.charset.Charset)" because "src" is null
    /// ```
    ///
    /// `Base64$Decoder.decode(Ljava/lang/String;)[B` was the LAST of the four
    /// to be fixed: it defaulted a null to `String::new()` and returned an
    /// EMPTY `byte[]`, which is why `RJdkIntrinsics2 --only=b64` reported
    /// "decode((String) null) must throw NullPointerException, got none" while
    /// the other three arms were already patched. Returning `Ok(None)` is
    /// equally wrong — every descriptor here returns a value, so `Ok(None)` is
    /// the VOID shape.
    ///
    /// Mutation check: revert any one arm to `Ok(None)` or to a defaulted
    /// empty input and exactly that row fails.
    #[test]
    fn null_argument_throws_npe_on_every_value_returning_overload() {
        fn assert_npe(label: &str, result: MethodCallResult) {
            match result {
                Err(MethodCallFailed::InternalError(VmError::Runtime(
                    RuntimeError::NullPointerException { .. },
                ))) => {}
                Ok(Some(v)) => {
                    panic!("{label}: returned {v:?}, HotSpot throws NullPointerException")
                }
                Ok(None) => panic!(
                    "{label}: returned the VOID shape `Ok(None)` for a descriptor that returns a \
                     value — the interpreter gets a value of the wrong kind"
                ),
                Err(other) => panic!("{label}: threw {other:?}, expected NullPointerException"),
            }
        }

        // Every (factory, method) pair whose descriptor takes a reference
        // argument, across all three variants.
        let encoder_factories: [(&str, NativeCallback); 3] = [
            ("basic", native_b64_get_encoder),
            ("url", native_b64_get_url_encoder),
            ("mime", native_b64_get_mime_encoder),
        ];
        let decoder_factories: [(&str, NativeCallback); 3] = [
            ("basic", native_b64_get_decoder),
            ("url", native_b64_get_url_decoder),
            ("mime", native_b64_get_mime_decoder),
        ];

        for (variant, factory) in encoder_factories {
            let mut ctx = MockNativeContext::new();
            let enc = match factory(&mut ctx, &[])
                .expect("factory ok")
                .expect("encoder")
            {
                Value::Object(Some(o)) => o,
                other => panic!("expected encoder, got {other:?}"),
            };
            let null_arg = [Value::Object(Some(enc)), Value::Object(None)];
            assert_npe(
                &format!("{variant} Encoder.encode((byte[])null)"),
                native_b64_encode(&mut ctx, &null_arg),
            );
            assert_npe(
                &format!("{variant} Encoder.encodeToString(null)"),
                native_b64_encode_to_string(&mut ctx, &null_arg),
            );
            // …and through withoutPadding(), which returns a DIFFERENT object.
            let unpadded = match native_b64_without_padding(&mut ctx, &[Value::Object(Some(enc))])
                .expect("withoutPadding ok")
                .expect("encoder")
            {
                Value::Object(Some(o)) => o,
                other => panic!("expected encoder, got {other:?}"),
            };
            assert_npe(
                &format!("{variant} Encoder.withoutPadding().encodeToString(null)"),
                native_b64_encode_to_string(
                    &mut ctx,
                    &[Value::Object(Some(unpadded)), Value::Object(None)],
                ),
            );
        }

        for (variant, factory) in decoder_factories {
            let mut ctx = MockNativeContext::new();
            let dec = match factory(&mut ctx, &[])
                .expect("factory ok")
                .expect("decoder")
            {
                Value::Object(Some(o)) => o,
                other => panic!("expected decoder, got {other:?}"),
            };
            let null_arg = [Value::Object(Some(dec)), Value::Object(None)];
            assert_npe(
                &format!("{variant} Decoder.decode((byte[])null)"),
                native_b64_decode_bytes(&mut ctx, &null_arg),
            );
            // THE ROW THAT WAS FAILING.
            assert_npe(
                &format!("{variant} Decoder.decode((String)null)"),
                native_b64_decode_string(&mut ctx, &null_arg),
            );
        }
    }

    /// The null-argument fix must not swallow the legitimate EMPTY input:
    /// HotSpot returns a zero-length array for `decode("")` and
    /// `decode(new byte[0])`, and that is exactly the answer the broken
    /// `decode((String) null)` used to give — so this is the negative control
    /// that keeps the fix from being "throw on anything falsy".
    #[test]
    fn empty_input_still_decodes_to_an_empty_array() {
        let mut ctx = MockNativeContext::new();
        let dec = match native_b64_get_decoder(&mut ctx, &[])
            .expect("getDecoder ok")
            .expect("decoder")
        {
            Value::Object(Some(o)) => o,
            other => panic!("expected decoder, got {other:?}"),
        };
        let empty_str = ctx.create_string("");
        let decoded = match native_b64_decode_string(
            &mut ctx,
            &[Value::Object(Some(dec)), Value::Object(Some(empty_str))],
        )
        .expect("decode(\"\") must NOT throw")
        .expect("decode returns an array")
        {
            Value::Object(Some(o)) => o,
            other => panic!("expected byte[], got {other:?}"),
        };
        assert_eq!(
            ctx.array_length(decoded),
            0,
            "decode(\"\") is empty, not a throw"
        );
    }

    // ---------------------------------------------------------------------
    // Below: BEHAVIOURAL cover for the fabricated receiver. Every assertion
    // reads a value the native WROTE, or an answer the native COMPUTED from a
    // receiver's fields — never "the triple is registered". A sibling file's 64
    // registration-only tests all stayed green through a real layout defect.
    // ---------------------------------------------------------------------

    fn obj(result: MethodCallResult, what: &str) -> ObjectRef {
        match result.unwrap_or_else(|e| panic!("{what} failed: {e:?}")) {
            Some(Value::Object(Some(o))) => o,
            other => panic!("{what}: expected an object, got {other:?}"),
        }
    }

    fn encode_to_string(ctx: &mut MockNativeContext, enc: ObjectRef, src: &[u8]) -> String {
        let arr = ctx.new_array(ArrayElementType::Byte, src.len());
        for (i, &b) in src.iter().enumerate() {
            ctx.set_array_element(arr, i, Value::Int(b as i32));
        }
        let s = obj(
            native_b64_encode_to_string(ctx, &[Value::Object(Some(enc)), Value::Object(Some(arr))]),
            "encodeToString",
        );
        ctx.read_string(s).expect("encodeToString returns a String")
    }

    /// Give an encoder the field values real `Base64.getMimeEncoder(20, {'\n'})`
    /// bytecode would have built, since that factory is deliberately
    /// unregistered and this file therefore never allocates such an object
    /// itself.
    fn retune(ctx: &mut MockNativeContext, enc: ObjectRef, linemax: i32, sep: &[u8]) {
        let nl = ctx.new_array(ArrayElementType::Byte, sep.len());
        for (i, &b) in sep.iter().enumerate() {
            ctx.set_array_element(nl, i, Value::Int(b as i32));
        }
        ctx.set_field(enc, B64_ENCODER_FIELD_LINEMAX, Value::Int(linemax));
        ctx.set_field(enc, B64_ENCODER_FIELD_NEWLINE, Value::Object(Some(nl)));
    }

    /// (1) The fabricated `Encoder` must carry all FOUR JDK fields.
    ///
    /// `newline` was left unwritten, and real `Encoder.encodedOutLength` reads
    /// `newline.length` for EVERY encode call whose `linemax > 0` — not only
    /// ones long enough to wrap. Measured on HotSpot by building the same shape
    /// through the private constructor (`scratchpad/e14/B64Fab.java`):
    ///
    /// ```text
    /// Encoder(false, null, 76, true).encodeToString(30 bytes) ->
    ///   NullPointerException / Cannot read the array length because "this.newline" is null
    /// Encoder(false, {13,10}, 76, true).encodeToString(60 bytes) -> 82  (== getMimeEncoder())
    /// ```
    ///
    /// The mock's unwritten slots read back as `Value::Int(0)`, so the
    /// `Value::Object(None)` assertions below fail if the explicit null write is
    /// dropped — they measure the WRITE, not the default.
    #[test]
    fn fabricated_encoders_carry_the_jdk_newline_and_linemax_fields() {
        let mut ctx = MockNativeContext::new();

        let mime = obj(native_b64_get_mime_encoder(&mut ctx, &[]), "getMimeEncoder");
        assert_eq!(
            ctx.get_field(mime, B64_ENCODER_FIELD_LINEMAX),
            Value::Int(76)
        );
        let nl = match ctx.get_field(mime, B64_ENCODER_FIELD_NEWLINE) {
            Value::Object(Some(a)) => a,
            other => panic!(
                "getMimeEncoder()'s `newline` is {other:?}; real encode0 and encodedOutLength \
                 both dereference it, and HotSpot NPEs on a null one"
            ),
        };
        assert_eq!(ctx.array_length(nl), 2, "CRLF is two bytes");
        assert_eq!(ctx.get_array_element(nl, 0), Value::Int(13));
        assert_eq!(ctx.get_array_element(nl, 1), Value::Int(10));

        // (2) -1, NOT 0, for the non-wrapping encoders. `> 0` reads them alike;
        // `Base64$EncOutputStream`'s `linepos == linemax` does not, and with 0 it
        // fires on the very first byte: `getEncoder().wrap(os)` measured as
        // NullPointerException / Cannot read the array length because "b" is null.
        for (name, factory) in [
            ("getEncoder", native_b64_get_encoder as NativeCallback),
            ("getUrlEncoder", native_b64_get_url_encoder),
        ] {
            let enc = obj(factory(&mut ctx, &[]), name);
            assert_eq!(
                ctx.get_field(enc, B64_ENCODER_FIELD_LINEMAX),
                Value::Int(-1),
                "{name}: real JDK writes -1; 0 makes the unregistered wrap(OutputStream) \
                 throw NullPointerException on its first write"
            );
            assert_eq!(
                ctx.get_field(enc, B64_ENCODER_FIELD_NEWLINE),
                Value::Object(None),
                "{name}: `newline` must be written null explicitly, not left as the \
                 allocator found it"
            );
        }
    }

    /// (2) A custom `linemax`/`newline` must reach the encoder.
    ///
    /// `Base64.getMimeEncoder(int, byte[])` is unregistered, so it runs real
    /// bytecode and hands back an `Encoder` with `linemax=20, newline=[10]`;
    /// `encodeToString` on it is then intercepted here. HotSpot answers **83**
    /// for the 60-byte fixture and this file used to answer **82** — one short,
    /// because it re-derived 76/CRLF from a variant tag. 82 vs 83 is the
    /// dangerous kind of wrong: both round-trip through a MIME decoder and both
    /// pass a length-is-about-right assertion. So assert the TEXT.
    #[test]
    fn a_custom_linemax_and_separator_reach_the_encoder() {
        let mut ctx = MockNativeContext::new();
        let payload: Vec<u8> = (0..60u16).map(|i| i as u8).collect();

        let canonical = obj(native_b64_get_mime_encoder(&mut ctx, &[]), "getMimeEncoder");
        assert_eq!(
            encode_to_string(&mut ctx, canonical, &payload).len(),
            82,
            "getMimeEncoder(): 80 chars + one CRLF"
        );

        let custom = obj(native_b64_get_mime_encoder(&mut ctx, &[]), "getMimeEncoder");
        retune(&mut ctx, custom, 20, b"\n");
        let encoded = encode_to_string(&mut ctx, custom, &payload);
        assert_eq!(
            encoded,
            "AAECAwQFBgcICQoLDA0O\nDxAREhMUFRYXGBkaGxwd\nHh8gISIjJCUmJygpKiss\nLS4vMDEyMzQ1Njc4OTo7",
            "four 20-char lines separated by LF"
        );
        assert_eq!(
            encoded.len(),
            83,
            "HotSpot: 83. The hardcoded 76/CRLF gave 82"
        );
    }

    /// (2, cont.) `withoutPadding()` COPIES the fields; it does not rebuild the
    /// encoder from a variant. Rebuilding silently reset a custom 20/LF encoder
    /// to 76/CRLF. Measured on HotSpot:
    /// `getMimeEncoder(20,{'\n'}).withoutPadding()` keeps `linemax=20`,
    /// `newline=[10]`, and encodes 61 bytes to 86 (88 with padding).
    #[test]
    fn without_padding_preserves_a_custom_linemax_and_shares_the_separator() {
        let mut ctx = MockNativeContext::new();
        let padded = obj(native_b64_get_mime_encoder(&mut ctx, &[]), "getMimeEncoder");
        retune(&mut ctx, padded, 20, b"\n");
        let sep = ctx.get_field(padded, B64_ENCODER_FIELD_NEWLINE);

        let unpadded = obj(
            native_b64_without_padding(&mut ctx, &[Value::Object(Some(padded))]),
            "withoutPadding",
        );
        assert_ne!(
            unpadded, padded,
            "a PADDED encoder returns a fresh object (HotSpot: \
             enc.withoutPadding() == enc.withoutPadding() is false)"
        );
        assert_eq!(
            ctx.get_field(unpadded, B64_ENCODER_FIELD_LINEMAX),
            Value::Int(20),
            "the copy must keep the custom linemax, not fall back to 76"
        );
        assert_eq!(
            ctx.get_field(unpadded, B64_ENCODER_FIELD_NEWLINE),
            sep,
            "real JDK passes the SAME newline array to the copy"
        );

        let payload = vec![0u8; 61];
        assert_eq!(encode_to_string(&mut ctx, padded, &payload).len(), 88);
        assert_eq!(encode_to_string(&mut ctx, unpadded, &payload).len(), 86);

        // …and an ALREADY-unpadded encoder returns `this` (HotSpot: identity true).
        let again = obj(
            native_b64_without_padding(&mut ctx, &[Value::Object(Some(unpadded))]),
            "withoutPadding",
        );
        assert_eq!(again, unpadded);
    }

    /// (1, cont.) An encoder with `linemax > 0` and a null `newline` is the
    /// exact shape this file used to fabricate, and HotSpot throws
    /// `NullPointerException` for it on every encode call. Reproduce the throw
    /// rather than quietly defaulting to CRLF — a default would give a plausible
    /// answer for an object the JDK considers malformed.
    #[test]
    fn a_wrapping_encoder_with_a_null_newline_throws_npe() {
        let mut ctx = MockNativeContext::new();
        let enc = obj(native_b64_get_mime_encoder(&mut ctx, &[]), "getMimeEncoder");
        ctx.set_field(enc, B64_ENCODER_FIELD_NEWLINE, Value::Object(None));
        let arr = ctx.new_array(ArrayElementType::Byte, 30);
        match native_b64_encode_to_string(
            &mut ctx,
            &[Value::Object(Some(enc)), Value::Object(Some(arr))],
        ) {
            Err(MethodCallFailed::InternalError(VmError::Runtime(
                RuntimeError::NullPointerException { .. },
            ))) => {}
            other => panic!(
                "linemax=76 with a null newline must throw NullPointerException \
                 (HotSpot: Cannot read the array length because \"this.newline\" is null), got {other:?}"
            ),
        }
        // A NON-wrapping encoder with a null newline is perfectly legal — that
        // is what `getEncoder()` is — so the throw must not generalise.
        let basic = obj(native_b64_get_encoder(&mut ctx, &[]), "getEncoder");
        assert_eq!(encode_to_string(&mut ctx, basic, &[0u8; 30]).len(), 40);
    }

    /// (4) The `Decoder` synthetic must be the real JDK's TWO-boolean layout.
    ///
    /// It was one Int slot holding a variant tag, and slot 0 of the real layout
    /// is `isURL` — so `getMimeDecoder()` wrote 2 into `isURL` and left `isMIME`
    /// false. Measured on HotSpot by building `Decoder(isURL=true, isMIME=false)`
    /// through the private constructor and feeding it what a MIME decoder must
    /// accept (`scratchpad/e14/B64Unreg.java`): 76-column wrapped text became
    /// `IllegalArgumentException / Illegal base64 character d`, `"-_-_"` decoded
    /// to 3 bytes instead of 0, `"QQ\n=="` threw instead of decoding to 1 byte.
    ///
    /// Both halves are asserted: the field VALUES (what real bytecode reads) and
    /// the decode ANSWERS (what this file's own natives compute from them).
    #[test]
    fn decoder_uses_the_two_boolean_jdk_layout() {
        let mut ctx = MockNativeContext::new();
        // (factory, isURL, isMIME) — read off HotSpot with reflection.
        let rows: [(&str, NativeCallback, i32, i32); 3] = [
            ("getDecoder", native_b64_get_decoder, 0, 0),
            ("getUrlDecoder", native_b64_get_url_decoder, 1, 0),
            ("getMimeDecoder", native_b64_get_mime_decoder, 0, 1),
        ];
        for (name, factory, is_url, is_mime) in rows {
            let dec = obj(factory(&mut ctx, &[]), name);
            assert_eq!(
                ctx.get_field(dec, B64_DECODER_FIELD_IS_URL),
                Value::Int(is_url),
                "{name}: field 0 is `isURL`, and real bytecode reads it as a boolean"
            );
            assert_eq!(
                ctx.get_field(dec, B64_DECODER_FIELD_IS_MIME),
                Value::Int(is_mime),
                "{name}: field 1 is `isMIME`"
            );
        }

        // The three variants must still answer differently — this is what the
        // old layout broke, by making the MIME decoder read back as a URL one.
        // `None` means the decoder threw, which is a legitimate answer here.
        //
        // `-_-_` is the input with THREE different correct answers across the
        // variants, so it alone separates all three field pairs above.
        assert_eq!(
            decode_len(
                &mut ctx,
                native_b64_get_url_decoder,
                "getUrlDecoder",
                "-_-_"
            ),
            Some(3),
            "the URL alphabet decodes -_-_ to 3 bytes"
        );
        assert_eq!(
            decode_len(
                &mut ctx,
                native_b64_get_mime_decoder,
                "getMimeDecoder",
                "-_-_"
            ),
            Some(0),
            "MIME IGNORES them -> empty. Under the old layout this decoder read \
             back as URL and answered 3."
        );
        assert_eq!(
            decode_len(&mut ctx, native_b64_get_decoder, "getDecoder", "-_-_"),
            None,
            "BASIC rejects them"
        );
        // A CRLF-wrapped payload: MIME accepts, BASIC rejects.
        assert_eq!(
            decode_len(
                &mut ctx,
                native_b64_get_mime_decoder,
                "getMimeDecoder",
                "QQ\r\n=="
            ),
            Some(1)
        );
        assert_eq!(
            decode_len(&mut ctx, native_b64_get_decoder, "getDecoder", "QQ\r\n=="),
            None
        );
    }

    /// Decoded length through a factory's decoder, or `None` when it threw.
    fn decode_len(
        ctx: &mut MockNativeContext,
        factory: NativeCallback,
        name: &str,
        text: &str,
    ) -> Option<usize> {
        let dec = obj(factory(ctx, &[]), name);
        let s = ctx.create_string(text);
        match native_b64_decode_string(ctx, &[Value::Object(Some(dec)), Value::Object(Some(s))]) {
            Ok(Some(Value::Object(Some(a)))) => Some(ctx.array_length(a)),
            Ok(other) => panic!("{name}.decode({text:?}): expected a byte[], got {other:?}"),
            Err(_) => None,
        }
    }

    /// (3) The six no-arg factories are SINGLETONS on HotSpot — `==`, not
    /// `equals` (`scratchpad/e14/B64Ident.java`, all six rows `true`) — and the
    /// singletons are the JDK's own `Encoder.RFC4648` / `RFC4648_URLSAFE` /
    /// `RFC2045` statics and the three matching ones on `Decoder`.
    ///
    /// So the fix is to RETURN THE JDK'S FIELD, not to memoize a fabricated
    /// object in a native `static`. A cache would reproduce `getEncoder() ==
    /// getEncoder()` but not this, also measured:
    ///
    /// ```text
    /// Base64.getMimeEncoder(0, sep) == Base64.getEncoder() -> true
    /// ```
    ///
    /// because `getMimeEncoder(int, byte[])` is unregistered, runs real
    /// bytecode, and returns the real `RFC4648` for any `lineLength <= 0`.
    ///
    /// This test DECLARES the static field on the mock rather than relying on a
    /// name-to-slot fallback, so it measures the lookup and not the mock.
    #[test]
    fn the_factories_return_the_jdk_singleton_when_there_is_one() {
        use cratonvm_native_api::FieldMetadata;
        let mut ctx = MockNativeContext::new();
        let cid = ctx
            .ensure_class_initialized("java/util/Base64$Encoder")
            .expect("class");
        let marker = obj(
            native_b64_get_mime_encoder(&mut ctx, &[]),
            "stand-in object",
        );
        ctx.set_declared_fields(
            cid,
            vec![FieldMetadata {
                name: "RFC4648".to_string(),
                descriptor: "Ljava/util/Base64$Encoder;".to_string(),
                access_flags: 0x0008, // ACC_STATIC
                slot_index: 0,
                declaring_class_id: cid,
                is_static: true,
            }],
        );
        ctx.set_static_field(cid, 0, Value::Object(Some(marker)));

        let first = obj(native_b64_get_encoder(&mut ctx, &[]), "getEncoder");
        let second = obj(native_b64_get_encoder(&mut ctx, &[]), "getEncoder");
        assert_eq!(
            first, marker,
            "getEncoder() must hand back java.util.Base64$Encoder.RFC4648 itself"
        );
        assert_eq!(first, second, "HotSpot: getEncoder() == getEncoder()");
    }

    /// …and the fallback is what keeps the row above from being a regression in
    /// synthetic-JDK mode, where there is no `RFC4648` field to take. With no
    /// declared static the factory must fabricate, exactly as before, and the
    /// fabricated object must still be usable.
    #[test]
    fn the_factories_fabricate_when_there_is_no_jdk_singleton() {
        let mut ctx = MockNativeContext::new();
        let first = obj(native_b64_get_encoder(&mut ctx, &[]), "getEncoder");
        let second = obj(native_b64_get_encoder(&mut ctx, &[]), "getEncoder");
        assert_ne!(
            first, second,
            "with no real class library there is nothing to be a singleton OF; \
             fabricating a fresh encoder is the documented fallback"
        );
        assert_eq!(encode_to_string(&mut ctx, first, b"\xff\xff\xff").len(), 4);
    }
}

#[cfg(test)]
mod nio_heap_byte_buffer_tests {
    use super::*;
    use crate::test_utils::MockNativeContext;
    #[allow(unused_imports)]
    use cratonvm_native_api::{
        NativeClassAccess, NativeExceptionAccess, NativeGpuAccess, NativeHeapAccess,
        NativeInvokeAccess, NativeSystemAccess, NativeThreadAccess,
    };
    use cratonvm_types::ArrayElementType;

    #[test]
    fn bytebuffer_allocate_initializes_real_address_for_bulk_copy() {
        let mut ctx = MockNativeContext::new();
        let result = native_heap_bytebuffer_allocate(&mut ctx, &[Value::Int(8)])
            .expect("ByteBuffer.allocate native succeeds")
            .expect("ByteBuffer.allocate returns object");
        let buffer = match result {
            Value::Object(Some(buffer)) => buffer,
            other => panic!("expected ByteBuffer object, got {other:?}"),
        };

        assert_eq!(ctx.get_field_by_name(buffer, "position"), Value::Int(0));
        assert_eq!(ctx.get_field_by_name(buffer, "limit"), Value::Int(8));
        assert_eq!(ctx.get_field_by_name(buffer, "capacity"), Value::Int(8));
        assert_eq!(ctx.get_field_by_name(buffer, "mark"), Value::Int(-1));
        assert_eq!(ctx.get_field_by_name(buffer, "offset"), Value::Int(0));
        assert_eq!(ctx.get_field_by_name(buffer, "address"), Value::Long(16));
        let hb = match ctx.get_field_by_name(buffer, "hb") {
            Value::Object(Some(hb)) => hb,
            other => panic!("expected hb byte array, got {other:?}"),
        };
        assert_eq!(ctx.array_length(hb), 8);
    }

    #[test]
    fn heap_byte_buffer_memorysegment_constructors_initialize_real_fields() {
        let mut registry = NativeMethodRegistry::new();
        register_essential_natives(&mut registry);
        for descriptor in [
            "([BIILjava/lang/foreign/MemorySegment;)V",
            "([BIILjdk/internal/access/foreign/MemorySegmentProxy;)V",
        ] {
            assert!(
                registry
                    .find("java/nio/HeapByteBuffer", "<init>", descriptor)
                    .is_some(),
                "HeapByteBuffer constructor {descriptor} must be native in real-JDK mode"
            );
        }

        let init = registry
            .find(
                "java/nio/HeapByteBuffer",
                "<init>",
                "([BIILjdk/internal/access/foreign/MemorySegmentProxy;)V",
            )
            .expect("JDK17 HeapByteBuffer(byte[],int,int,segment) native");

        let mut ctx = MockNativeContext::new();
        let buffer_class = ctx
            .ensure_class_initialized("java/nio/HeapByteBuffer")
            .expect("mock HeapByteBuffer class");
        let buffer = ctx.alloc_object(buffer_class, 8);
        let bytes = ctx.new_array(ArrayElementType::Byte, 6);

        init(
            &mut ctx,
            &[
                Value::Object(Some(buffer)),
                Value::Object(Some(bytes)),
                Value::Int(2),
                Value::Int(3),
                Value::Object(None),
            ],
        )
        .expect("constructor native succeeds");

        assert_eq!(ctx.get_field_by_name(buffer, "mark"), Value::Int(-1));
        assert_eq!(ctx.get_field_by_name(buffer, "position"), Value::Int(2));
        assert_eq!(ctx.get_field_by_name(buffer, "limit"), Value::Int(5));
        assert_eq!(ctx.get_field_by_name(buffer, "capacity"), Value::Int(6));
        assert_eq!(
            ctx.get_field_by_name(buffer, "hb"),
            Value::Object(Some(bytes))
        );
        assert_eq!(ctx.get_field_by_name(buffer, "offset"), Value::Int(0));
        assert_eq!(ctx.get_field_by_name(buffer, "address"), Value::Long(16));
    }
}

#[cfg(test)]
mod charset_alias_tests {
    use super::*;
    use crate::test_utils::MockNativeContext;
    #[allow(unused_imports)]
    use cratonvm_native_api::{
        NativeClassAccess, NativeExceptionAccess, NativeGpuAccess, NativeHeapAccess,
        NativeInvokeAccess, NativeSystemAccess, NativeThreadAccess,
    };

    #[test]
    fn charset_for_name_initializes_alias_fields_and_aliases_native_caches_set() {
        let mut registry = NativeMethodRegistry::new();
        register_charset_natives(&mut registry);
        let for_name = registry
            .find(
                "java/nio/charset/Charset",
                "forName",
                "(Ljava/lang/String;)Ljava/nio/charset/Charset;",
            )
            .expect("Charset.forName native");
        let aliases = registry
            .find("java/nio/charset/Charset", "aliases", "()Ljava/util/Set;")
            .expect("Charset.aliases native");

        let mut ctx = MockNativeContext::new();
        let name = ctx.create_string("UTF-8");
        let charset = match for_name(&mut ctx, &[Value::Object(Some(name))])
            .expect("forName succeeds")
            .expect("forName returns value")
        {
            Value::Object(Some(o)) => o,
            other => panic!("forName should return Charset, got {other:?}"),
        };

        let alias_array = match ctx.get_field_by_name(charset, "aliases") {
            Value::Object(Some(o)) => o,
            other => panic!("Charset.aliases field should be an empty array, got {other:?}"),
        };
        assert_eq!(ctx.array_length(alias_array), 0);
        assert_eq!(
            ctx.get_field_by_name(charset, "aliasSet"),
            Value::Object(None)
        );

        let alias_set = match aliases(&mut ctx, &[Value::Object(Some(charset))])
            .expect("aliases native succeeds")
            .expect("aliases returns value")
        {
            Value::Object(Some(o)) => o,
            other => panic!("aliases should return Set, got {other:?}"),
        };
        assert_eq!(
            ctx.get_field_by_name(charset, "aliasSet"),
            Value::Object(Some(alias_set))
        );
    }
}

